begin;

-- ── Products ─────────────────────────────────────────────────
insert into products (handle, title, body_html, vendor, type, tags, status, badge, rating, review_count, min_price, sort_order)
values
  ('built-better-tee-ss', 'Built Better Tee S/S', '<p>Constructed of heavyweight garment-dyed, 100% ringspun cotton from Comfort Colors®, the Built Better Tee S/S features two mallards in flight over an octagonal marsh background with cursive Chêne styling. It also includes a front chest pocket.</p>', 'Chêne Gear', 'T-Shirts', '{"activity:lifestyle","audience:mens","material:cotton"}', 'active', 'Best Seller', 4.9, 215, 35, 801),
  ('logo-tee-ss', 'Logo Tee S/S', 'The Logo Tee S/S features the Chêne Gear sigil upon the front chest and is i<span data-mce-fragment="1">deal f</span><span data-mce-fragment="1">or the times when your mind is in the woods, but your body isn''t</span>. It''s constructed with a tri-blend of fabrics (50% polyester / 25% ringspun cotton / 25% rayon), making it ultra-lightweight, comfortable, and breathable.', 'Chêne Gear', 'T-Shirts', '{"activity:lifestyle","audience:mens","material:cotton"}', 'active', 'Best Seller', 4.8, 187, 35, 802),
  ('sherpa-fleece-wader-pant', 'Sherpa Fleece Wader Pant', '<p>When mornings start with visible exhales and busting through ice, grab the Sherpa Fleece Wader Pant. The perfect compliment to 2S Waders, these pants aren''t short on warmth or comfort. The sherpa fleece lining and built-in stretch make sure of that. The tapered fit and integrated stirrups keep everything in place and bunch-free.</p>', 'Chêne Gear', 'Pants', '{"activity:waterfowl","audience:mens","boldmetrics:mens_wader_pant_alpha","feature:insulated","material:fleece","material:polyester","sub:bottom","sub:insulated"}', 'active', NULL, 4.8, 12, 230, 603),
  ('performance-hoodie', 'Performance Hoodie', '<p>An athletic fit and performance fleece make this hoodie capable of just that…performing. Layer easily with the integrated thumbholes or wear it solo when cooler days are accompanied by a longer to-do list.</p>', 'Chêne Gear', 'Hoodies', '{"activity:lifestyle","audience:mens","boldmetrics:mens_perform_hoodie_alpha"}', 'active', 'Best Seller', 4.9, 143, 80, 904),
  ('chene-rectangle-sticker', 'Chêne Rectangle Sticker', '<p>Wherever your love for adventure takes you, outfit your gear with the Chêne Rectangle Sticker. Made of thick, durable vinyl that protects from scratches, water, and sunlight. Measures 6" x 2.09".</p>', 'Chêne Gear', 'Accessories', '{"channel:retail-only","hide-from-all-products","merch:no-upsell","sub:stickers"}', 'active', NULL, 4.8, 12, 5, 1205),
  ('chene-transfer-sticker', 'Chene Transfer Sticker', '<p>Wherever your love for adventure takes you, outfit your gear with the Chêne Transfer Sticker. Ideal for both indoor and outdoor use, especially on vehicle windows. Measures 5" x 1.61".</p>', 'Chêne Gear', 'Accessories', '{"channel:retail-only","hide-from-all-products","merch:no-upsell","sub:stickers"}', 'active', NULL, 4.8, 12, 5, 1206),
  ('leisure-hoodie', 'Leisure Hoodie', '<p>The hoodie you''ll turn to when comfort is the goal. The soft fleece interior and looser fit make for an easy-wearing staple suited for tackling the camp to-do list or some fireside cold ones.</p>', 'Chêne Gear', 'Hoodies', '{"activity:lifestyle","audience:mens","boldmetrics:mens_delta_hoodie_alpha"}', 'active', NULL, 4.8, 12, 80, 907),
  ('chene-license-plate', 'Logo License Plate', '<p>Take Chêne Gear with you on the road with the Chêne License Plate - the perfect complement to your truck, trailer, or hunting lodge. The license plate is made from cast aluminum and follows standard automotive sizing.</p>', 'Chêne Gear', 'Accessories', '{"activity:lifestyle"}', 'active', NULL, 4.8, 12, 20, 1208),
  ('patch-logo-camo-cotton-cap', 'Patch Logo Cotton Camo Cap', '<p>Chêne Gear''s unstructured caps deliver a low-profile, relaxed fit and soft twill construction, the kind of hat that looks like it''s been with you a few seasons, right out of the box. Adjustable strap closure provides a dialed-in fit.</p>', 'Chêne Gear', 'Headwear', '{"activity:lifestyle"}', 'active', NULL, 4.8, 12, 35, 1109),
  ('6-panel-waxed-cotton-cap', '6-Panel Waxed Cotton Cap', '<p>The same heritage material as the Chêne Gear Wax Canvas line, now in a cap. Waxed cotton construction that develops character with every hunt, water-resistant, naturally stiff, and built to soften and shape to you over time. An adjustable strap closure and clean profile make it versatile in and out of the field.</p>', 'Chêne Gear', 'Headwear', '{"activity:lifestyle"}', 'active', NULL, 4.8, 12, 35, 1110),
  ('digital-gift-card', 'Digital Gift Card', '<p>Give the gift of choice. If you''re unsure on what to get them or stuck between sizes or patterns, a digital gift card from Chêne Gear ensures they always get the perfect gift. Digital gift cards are delivered via email and contain instructions on how to redeem them upon checkout. Digital gift cards have no additional processing fees. If the digital gift card is being purchased for someone else, simply forward the email to the recipient.</p>  <p>NOTE: This item is non-refundable.</p>', 'Chêne Gear', 'Gift Card', '{"merch:no-upsell"}', 'active', NULL, 4.8, 12, 20, 9911),
  ('over-under-jacket', 'Over/Under Jacket', '<p>A tale of two halves. The upper half of the Over/Under Jacket features added insulation for extra warmth where it''s needed. From your wader line down, the tapered fit ensures less bulk and top-tier comfort thanks to the sherpa fleece lining.</p>', 'Chêne Gear', 'Jackets', '{"activity:lifestyle","activity:waterfowl","audience:mens","boldmetrics:mens_over_under_alpha","feature:insulated","material:fleece","merch:corporate","series:over-under","sub:insulated","sub:mid-layer"}', 'active', NULL, 4.8, 12, 300, 212),
  ('hydro-lok-shell-jacket', 'Hydro-Lok Shell Jacket', '<p>Wind and rain go hand-in-hand with duck season, so we made the Hydro-Lok Shell Jacket. The three-layer construction offers superior water- and windproof protection with enough toughness to handle run-ins with brambles and rogue branches. An adjustable hood, hem, and cuffs keep water and wind from creeping in.</p>', 'Chêne Gear', 'Jackets', '{"activity:waterfowl","audience:mens","boldmetrics:mens_hydro_shell_alpha","feature:waterproof","series:hydro-lok","sub:shell"}', 'active', NULL, 4.8, 12, 400, 213),
  ('scout-vest', 'Scout Vest', '<p>Boat rides and ripping north winds, that''s what the Scout Vest was built for. The 100% windproof construction is paired with a fleece-lined interior that makes no sacrifices in comfort. Fleece-lined handwarmer pockets compliment a streamlined fit that layers easily throughout your kit.</p>', 'Chêne Gear', 'Vests', '{"activity:lifestyle","activity:turkey","activity:waterfowl","audience:mens","boldmetrics:mens_scout_vest_alpha","feature:breathable","feature:windproof","material:fleece","material:polyester","merch:corporate","series:scout","sub:shell"}', 'active', NULL, 4.8, 12, 200, 314),
  ('sixty-series-zip-with-hood', 'Sixty Series Technical Fleece Half Zip with Hood', '<p>Our Sixty Series gear is built for all-season versatility. Wear it solo on opening day or layer on top of it during the final stretch. Grid fleece delivers reliable warmth without sacrificing breathability and the streamlined fit layers easily without bunching.</p>', 'Chêne Gear', 'Base Layers', '{"activity:turkey","activity:waterfowl","audience:mens","boldmetrics:mens_60_series_alpha","feature:quick-dry","material:fleece","merch:corporate","series:sixty","sub:base-layer-top","sub:mid-layer"}', 'active', 'Best Seller', 5, 82, 160, 415),
  ('sixty-series-zip', 'Sixty Series Technical Fleece Half Zip', '<p data-mce-fragment="1">The Sixty Series Technical Fleece Half Zip is a versatile technical fleece that provides warmth and superior breathability. Built with high-performance, moisture wicking fabric that keeps you dry and regulates body temperatures during demanding hunts. Suitable as an outer layer on mild days, as well as a mid-layer during cold hunts. Sciessant Agion® antimicrobial treatment fights odor. Other features include large zippered chest pocket, lower fleece-lined hand warmer kangaroo pocket, stretch-fit cuff with thumb hole, and streamlined body-mapped fit.</p> <p data-mce-fragment="1"><meta charset="UTF-8"><em data-mce-fragment="1">Note: Please check the <a href="https://chenegear.com/pages/size-fit-guide" title="Size &amp; Fit Guide" data-mce-fragment="1" data-mce-href="https://chenegear.com/pages/size-fit-guide">Size &amp; Fit Guide</a> for your correct size.</em></p> <p data-mce-fragment="1"><iframe title="YouTube video player" src="https://www.youtube.com/embed/2A76-SrUJ-U" height="315" width="560" allowfullscreen="" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture" frameborder="0"></iframe><br></p>', 'Chêne Gear', 'Base Layers', '{"activity:turkey","activity:waterfowl","audience:mens","boldmetrics:mens_60_series_alpha","feature:quick-dry","material:fleece","merch:corporate","series:sixty","sub:base-layer-top","sub:mid-layer"}', 'active', NULL, 4.8, 12, 150, 416),
  ('merino-wool-top', 'Merino Mock Neck', '<p>Wool has been a staple in timber holes and treestands for generations, and rightfully so. It naturally wicks away moisture, mitigates odor, and it''s exceptionally warm, even if it''s soaked. The Merino Mock Neck uses the highest-quality wool to make the most of these performance traits with an upgrade to softness.</p>', 'Chêne Gear', 'Base Layers', '{"activity:turkey","activity:waterfowl","boldmetrics:mens_merino_quarter_alpha","material:merino","sub:base-layer-top"}', 'active', NULL, 4.8, 12, 110, 417),
  ('merino-wool-bottoms', 'Merino Bottom', '<p>Wool has been a staple in timber holes and treestands for generations, and rightfully so. It naturally wicks away moisture, mitigates odor, and it''s exceptionally warm, even if it''s soaked. The Merino Bottom uses the highest-quality wool to make the most of these performance traits with an upgrade to softness.</p>', 'Chêne Gear', 'Base Layers', '{"activity:turkey","activity:waterfowl","boldmetrics:mens_merino_bottom_alpha","material:merino","sub:base-layer-bottom"}', 'active', NULL, 4.8, 12, 110, 418),
  ('chene-short-sleeve-dog-stand-tee', 'Dog Stand Tee S/S', '<meta charset="UTF-8"><span data-mce-fragment="1">Constructed of heavyweight garment-dyed, 100% ringspun cotton from Comfort Colors®, the Dog Stand Tee S/S features a black lab next to a limit of mallards. It also includes a front chest pocket.</span>', 'Chêne Gear', 'T-Shirts', '{"activity:lifestyle","audience:mens","material:cotton"}', 'active', NULL, 4.8, 12, 35, 819),
  ('unstructured-6-panel-twill-delta-logo', 'Unstructured 6-Panel Twill Diacritic Cap', '<p>Chêne Gear''s unstructured caps deliver a low-profile, relaxed fit and soft twill construction, the kind of hat that looks like it''s been with you a few seasons, right out of the box. Adjustable strap closure provides a dialed-in fit.</p>', 'Chêne Gear', 'Headwear', '{"activity:lifestyle"}', 'active', NULL, 4.8, 12, 35, 1120),
  ('7-panel-wax-cap', '7-Panel Waxed Cotton Cap', '<p>The same heritage material as the Chêne Gear Wax Canvas line, now in a cap. Waxed cotton construction that develops character with every hunt, water-resistant, naturally stiff, and built to soften and shape to you over time. An adjustable strap closure and clean profile make it versatile in and out of the field.</p>', 'Chêne Gear', 'Headwear', '{"activity:lifestyle"}', 'active', NULL, 4.8, 12, 35, 1121),
  ('chene-patch-rope-hats', 'Rope Patch Cap', '<p>Chêne Gear''s rope caps deliver a curved brim, signature rope detail across the front, and a fit that feels broken in from day one. Built to wear hard and look good doing it. Snapback closure allows for an adjustable fit.</p>', 'Chêne Gear', 'Headwear', '{"activity:lifestyle"}', 'active', NULL, 4.8, 12, 35, 1122),
  ('neck-gaiter', 'Polar Fleece Neck Gaiter', '<p>Lightweight and versatile, the Polar Fleece Neck Gaiter pulls double duty as a neck wrap and a face covering when the wind picks up. Soft polar fleece construction keeps it comfortable against your skin through long sits. Wear it as a gaiter, pull it up as a mask, or fold it down as a collar. One piece, multiple setups.</p>', 'Chêne Gear', 'Headwear', '{"activity:lifestyle","sub:neck-gaiter"}', 'active', NULL, 4.8, 12, 30, 1123),
  ('6-panel-leather-patch-cap', '6-Panel Leather Patch Cap', '<p>Chêne Gear''s structured mesh-back caps feature a front panel that holds its shape season after season, paired with breathable, mesh back panels that keep you cool from the pre-dawn boat ride to the last retrieve of the day. A snapback closure allows for a dialed-in fit.</p>', 'Chêne Gear', 'Headwear', '{"activity:lifestyle"}', 'active', NULL, 4.8, 12, 35, 1124),
  ('kids-short-sleeve-logo-tee', 'Youth Logo Tee S/S', '<p><meta charset="UTF-8"><span data-mce-fragment="1">Constructed of heavyweight garment-dyed, 100% ring spun cotton from Comfort Colors®, the Youth Logo Tee S/S features the Chêne Logo on the front. </span></p> <p> </p> <p><span data-mce-fragment="1">Note: This is for kids sizing.</span></p>', 'Chêne Gear', 'T-Shirts', '{"activity:lifestyle","audience:youth","material:cotton"}', 'active', NULL, 4.8, 12, 25, 825),
  ('performance-oval-patch-cap', 'Performance Oval Patch Cap', '<p>When the temperature climbs and shows no sign of slowing down, the last thing you need is your hat working against you. Chêne Gear''s performance caps are built from lightweight, moisture-wicking fabric with a low-profile construction that stays out of your way. The adjustable closure provides a secure fit.</p>', 'Chêne Gear', 'Headwear', '{"activity:lifestyle"}', 'active', NULL, 4.8, 12, 35, 1126),
  ('chene-gear-wax-jacket', 'Waxed Canvas Jacket', '<p>Waxed canvas has been a long-standing staple in the duck woods. With solid durability, built-in weather protection and a worn-in feel to boot, it''s a no-brainer. The Waxed Canvas Jacket is fit to wear as your outermost layer and an array of pockets keep essential gear secure and in reach. A soft cotton lining adds a touch of warmth and comfort to this classic style.</p>', 'Chêne Gear', 'Jackets', '{"activity:waterfowl","audience:mens","feature:waterproof","feature:windproof","material:wax-canvas","series:wax-canvas","sub:shell"}', 'active', NULL, 4.8, 12, 450, 227),
  ('floodline-cornerstone-boot', 'Floodline Midweight Cornerstone Boot', '<p>Hunt or work. Rain or shine. The Floodline Cornerstone Boot excels in every setting. A three-part sole construction elevates comfort for full days in the field, even when carrying extra weight. Traction designed for every terrain and a full-length zipper round out the boot built to be put through the paces.</p>', 'Chêne Gear', 'Footwear', '{"activity:turkey","activity:waterfowl","audience:mens","feature:waterproof","material:rubber","series:floodline"}', 'active', NULL, 4.8, 12, 200, 728),
  ('crew-neck', 'Comfort Colors Sweatshirt', '<p>A classic style with ultra-soft construction makes this sweatshirt a wardrobe staple in cooler weather. The relaxed fit and 100% cotton construction make for reliable comfort in camp or around town.</p>', 'Chêne Gear', 'Sweaters', '{"activity:lifestyle","audience:mens","boldmetrics:mens_comfort_sweat_alpha","material:cotton"}', 'active', NULL, 4.8, 12, 50, 1029),
  ('chn7120-chene-richardson-wax-front-mesh-back-cap-bourbon', 'Waterfowl Co. Waxed Mesh Back Cap', '<p>The same heritage material as the Chêne Gear Wax Canvas line, now in a cap. Waxed cotton construction that develops character with every hunt, water-resistant, naturally stiff, and built to soften and shape to you over time. An adjustable strap closure and clean profile make it versatile in and out of the field.</p>', 'Chêne Gear', 'Headwear', '{"activity:lifestyle"}', 'active', NULL, 4.8, 12, 35, 1130),
  ('all-mesh-cap', 'All Mesh Cap', '<p>Chêne Gear''s structured mesh-back caps feature a front panel that holds its shape season after season, paired with breathable, mesh back panels that keep you cool from the pre-dawn boat ride to the last retrieve of the day. A snapback closure allows for a dialed-in fit.</p>', 'Chêne Gear', 'Headwear', '{"activity:lifestyle"}', 'active', NULL, 4.8, 12, 35, 1131),
  ('chn7600-chene-richardson-6-panel-diacritic-cap-brown-khaki', '6-Panel Diacritic Mesh Back Cap', '<p>Chêne Gear''s structured mesh-back caps feature a front panel that holds its shape season after season, paired with breathable, mesh back panels that keep you cool from the pre-dawn boat ride to the last retrieve of the day. A snapback closure allows for a dialed-in fit.</p>', 'Chêne Gear', 'Headwear', '{"activity:lifestyle"}', 'active', NULL, 4.8, 12, 35, 1132),
  ('flooded-timber-tee', 'Twin Oaks Tee S/S', '<meta charset="utf-8"><span>Constructed of heavyweight garment-dyed, 100% ringspun cotton from Comfort Colors®, the Flooded Timber Tee S/S features an image in the flooded bottoms of Arkansas. It also includes a front chest pocket.</span>', 'Chêne Gear', 'T-Shirts', '{"activity:lifestyle","audience:mens","material:cotton"}', 'active', NULL, 4.8, 12, 35, 833),
  ('pass-it-down-tee-s-s', 'Pass It Down Tee S/S', '<meta charset="utf-8"><span>Constructed of heavyweight garment-dyed, 100% ringspun cotton from Comfort Colors®, the Pass it down Tee S/S features an image of a father and son sharing a morning together. It also includes a front chest pocket.</span>', 'Chêne Gear', 'T-Shirts', '{"activity:lifestyle","audience:mens","material:cotton"}', 'active', NULL, 4.8, 12, 35, 834),
  ('hard-days-work-s-s', 'Ride Out Tee S/S', '<meta charset="utf-8"><span>Constructed of heavyweight garment-dyed, 100% ringspun cotton from Comfort Colors®, the Hard Days Work Tee S/S features an image on the back of a Bronco after a great day in the woods. It also includes a front chest pocket.</span>', 'Chêne Gear', 'T-Shirts', '{"activity:lifestyle","audience:mens","material:cotton"}', 'active', NULL, 4.8, 12, 35, 835),
  ('performance-rope-cap', 'Performance Rope Cap', '<p>Chêne Gear''s rope caps deliver a curved brim, signature rope detail across the front, and a fit that feels broken in from day one. Built to wear hard and look good doing it. Snapback closure allows for an adjustable fit.</p>', 'Chêne Gear', 'Headwear', '{"activity:lifestyle"}', 'active', NULL, 4.8, 12, 35, 1136),
  ('scout-deck-boot', 'Scout Deck Boot', '<p>If there''s moisture on the ground and work to be done, turn to the Scout Boot. The sturdy rubber overlay makes standing water and muck a non-factor. Full days spent on your feet are made easier thanks to a neoprene lining and midsole construction that prioritize comfort.</p>', 'Chêne Gear', 'Footwear', '{"activity:lifestyle","activity:turkey","activity:waterfowl","audience:mens","feature:waterproof","material:rubber","merch:bestseller","series:scout"}', 'active', 'Best Seller', 5, 343, 120, 737),
  ('floodline-slough-boot', 'Floodline Slough Boot', '<p>Thanks to a deployable waterproof extension, the Floodline Slough Boot goes from rubber boot workhorse to thigh-high waterproof protection in seconds. For hunts or workdays that turn semi-aquatic, the 4-layer construction keeps you completely dry when water crossings get a little tall. An air mesh grid liner boosts circulation and the EVA midsole furthers that comfort underfoot. Step with confidence in mud, muck, or even submerged thanks to the optimal tread pattern.</p>', 'Chêne Gear', 'Footwear', '{"activity:turkey","activity:waterfowl","audience:mens","feature:waterproof","material:rubber","series:floodline"}', 'active', NULL, 4.8, 12, 300, 738),
  ('field-stretch-pant', 'Field Pant', '<p>Depending on the day, "being in the field" could mean just about anything. Seeding, brush hogging, cutting shooting lanes, or setting an army of full-bodies, the Field Pant was designed to do it all. Using a construction that prioritizes complete mobility and a lineup of strategic pockets, the Field Pant makes no sacrifices in range of motion or utility.</p>', 'Chêne Gear', 'Pants', '{"activity:lifestyle","activity:turkey","activity:waterfowl","audience:mens","boldmetrics:mens_field_pant_num","feature:breathable","feature:water-resistant","material:polyester","sub:bottom","sub:mid-layer"}', 'active', NULL, 4.8, 12, 160, 639),
  ('chene-hydro-lok-bib', 'Hydro-Lok Field Bib', '<p>Using the same nylon fabric as our best-selling waders, the Hydro-Lok Field Bib brings weatherproof durability to drier ground. The three-layer construction offers superior waterproof and windproof protection with enough toughness to handle the wear and tear of field hunts. Magnetic flaps and oversized zippers on the legs easily manage encroaching mud and snow when dry feeds are on the docket.</p>', 'Chêne Gear', 'Bibs', '{"activity:waterfowl","audience:mens","boldmetrics:mens_hydro_bib_alpha","merch:bestseller","series:hydro-lok","sub:bottom","sub:shell"}', 'active', NULL, 4.8, 12, 500, 540),
  ('waxjac-shirt', 'Waxed Canvas Jac-Shirt', '<p>Waxed canvas is tough, it sheds moisture, and it looks good while doing it. The Waxed Canvas Jac-Shirt furthers that classic utility with custom brass buttons and a handful of useful pockets. A mesh lining adds more comfort for all day wear.</p>', 'Chêne Gear', 'Shirts', '{"activity:lifestyle","activity:waterfowl","boldmetrics:mens_wax_canvas_alpha","feature:water-resistant","material:wax-canvas","series:wax-canvas","sub:shell"}', 'active', NULL, 4.8, 12, 200, 9941),
  ('flyweigh-vest', 'Flyweigh Vest', '<p>Designed to provide warmth close to the body, the Flyweigh Vest is fit to be worn as a second layer with insulation that punches above its weight. Cut tighter to the body, this vest allows for an unrestricted range of motion even when layered on top of.</p>', 'Chêne Gear', 'Vests', '{"activity:lifestyle","activity:waterfowl","audience:mens","boldmetrics:mens_flyweigh_vest_alpha","feature:insulated","feature:windproof","material:primaloft","merch:corporate","series:flyweigh","sub:insulated"}', 'active', NULL, 4.8, 12, 200, 342),
  ('wax-canvas-timber-bag', 'Waxed Canvas Timber Bag', '<p>Simple and reliable construction, waxed canvas that will last for generations, and plenty of secure organization -- the Waxed Canvas Timber Bag is the last blind bag you''ll ever need. We started with materials that can easily handle the moisture and muck frequently encountered in the field. A slew of intentionally-designed pockets securely store everything from spinner wings to truck keys.</p>', 'Chêne Gear', 'Accessories', '{"activity:lifestyle","activity:waterfowl","material:wax-canvas","merch:corporate","series:wax-canvas","sub:bag"}', 'active', NULL, 4.8, 12, 350, 1243),
  ('chene-wax-canvas-double-layer-gun-sleeve', 'Waxed Canvas Gun Sleeve', '<p>Simple, sleek, made to work. The Waxed Canvas Gun Sleeve is built to protect your gun from moisture, mud, and contact with rough surfaces in transit. The classic construction limits bulk and it can be easily rolled up and stored when not in use.</p>', 'Chêne Gear', 'Accessories', '{"activity:waterfowl","material:wax-canvas","series:wax-canvas"}', 'active', NULL, 4.8, 12, 100, 1244),
  ('chene-flyweigh-jacket', 'Flyweigh Jacket', '<p>Drop the boat, push the RPM''s, set the spread, fill the strap, all without shedding layers. The Flyweigh Jacket is designed with enough warmth, breathability, and stretch to be comfortable for every step of the hunt. Wind- and water-resistant construction combined with top-tier insulation handle the elements with ease, and stretch panels provide total freedom of movement.</p>', 'Chêne Gear', 'Jackets', '{"activity:lifestyle","activity:waterfowl","boldmetrics:mens_flyweigh_jacket_alpha","feature:insulated","feature:windproof","merch:corporate","series:flyweigh","sub:insulated"}', 'active', NULL, 4.8, 12, 400, 245),
  ('chene-gear-bonded-fleece-field-stretch-pant', 'Bonded Fleece Field Pant', '<p>The Bonded Fleece Field Pant bridges the gap from early-season dry field hunts to late-season wader pants. The water-resistant exterior has built-in stretch for unrestricted movement and the fleece lining takes comfort up a notch. High-wear areas like the belt loops and waist closure have been reinforced and an array of pockets keep essentials in reach.</p>', 'Chêne Gear', 'Pants', '{"activity:lifestyle","activity:waterfowl","audience:mens","boldmetrics:mens_field_pant_num","feature:insulated","feature:water-resistant","feature:windproof","material:fleece","material:polyester","sub:bottom","sub:insulated"}', 'active', NULL, 4.8, 12, 180, 646),
  ('chene-gear-bonded-fleece-sherpa-pullover', 'Sherpa Fleece Quarter Zip', '<p>Windproof and water-resistant, the Sherpa Fleece Quarter Zip is a go-to when cold north winds start to pick up. The grid-fleece interior and sherpa fleece-lined kangaroo pocket make for comfort that''s hard to beat, fit to layer over or under waders.</p>', 'Chêne Gear', 'Jackets', '{"activity:lifestyle","activity:waterfowl","audience:mens","boldmetrics:mens_scout_jacket_alpha","feature:water-resistant","feature:windproof","material:fleece","material:polyester","sub:mid-layer"}', 'active', NULL, 4.8, 12, 300, 247),
  ('chene-gear-merino-wool-1-2-zip-with-hood', 'Merino Half Zip with Hood', '<p>Wool has been a staple in timber holes and treestands for generations, and rightfully so. It naturally wicks away moisture, mitigates odor, and it''s exceptionally warm, even if it''s soaked. The Merino Half Zip uses the highest-quality wool to make the most of these performance traits with an upgrade to softness.</p>', 'Chêne Gear', 'Base Layers', '{"activity:turkey","activity:waterfowl","boldmetrics:mens_merino_half_zip_alpha","material:merino","sub:base-layer-top"}', 'active', NULL, 4.8, 12, 125, 448),
  ('chene-gear-youth-over-and-under', 'Youth Over/Under Jacket', '<p>A tale of two halves. The upper half of the Over/Under Jacket features added insulation for extra warmth where it''s needed. From your wader line down, the tapered fit ensures less bulk and top-tier comfort thanks to the sherpa fleece lining.</p>  <p>Identical construction to the Adult Hydro-Lok Shell Jacket.</p>', 'Chêne Gear', 'Jackets', '{"activity:waterfowl","audience:youth","feature:insulated","material:fleece","series:over-under","sub:insulated","sub:mid-layer"}', 'active', NULL, 4.8, 12, 225, 249),
  ('chene-gear-youth-sherpa-fleece-wader-pant', 'Youth Sherpa Fleece Wader Pant', '<p>When mornings start with visible exhales and busting through ice, grab the Sherpa Fleece Wader Pant. The perfect compliment to 2S Waders, these pants aren''t short on warmth or comfort. The sherpa fleece lining and built-in stretch make sure of that. The tapered fit and integrated stirrups keep everything in place and bunch-free.</p>', 'Chêne Gear', 'Pants', '{"activity:waterfowl","audience:youth","feature:insulated","material:fleece","material:polyester","sub:bottom","sub:insulated"}', 'active', NULL, 4.8, 12, 175, 650),
  ('chene-gear-youth-hydro-lok', 'Youth Hydro-Lok Shell Jacket', '<p>Wind and rain go hand-in-hand with duck season, so we made the Hydro-Lock Shell Jacket. The three-layer construction offers superior water- and windproof protection with enough toughness to handle run-ins with brambles and rogue branches. An adjustable hood, hem, and cuffs keep water and wind from creeping in.</p>  <p>Identical construction to the Adult Hydro-Lok Shell Jacket.</p>', 'Chêne Gear', 'Jackets', '{"activity:waterfowl","audience:youth","feature:waterproof","series:hydro-lok","sub:shell"}', 'active', NULL, 4.8, 12, 300, 251),
  ('chene-logo-performance-rope-hat', 'Performance Rope Patch Cap', '<p>Chêne Gear''s rope caps deliver a curved brim, signature rope detail across the front, and a fit that feels broken in from day one. Built to wear hard and look good doing it. Snapback closure allows for an adjustable fit.</p>', 'Chêne Gear', 'Headwear', '{"activity:lifestyle"}', 'active', NULL, 4.8, 12, 35, 1152),
  ('coffee-table-book-volume-one', 'Coffee Table Book - Volume One', '<meta charset="utf-8"> <p data-mce-fragment="1"><span data-mce-fragment="1">In this 208 page, hardcover coffee table book you will experience the Chêne Gear obsession of waterfowl hunting. Featuring stunning photography, full recipes, hunting stories, underground photos and much more. </span></p> <p data-mce-fragment="1"><b data-mce-fragment="1">Limited quantities available.</b></p> <p data-mce-fragment="1"><b data-mce-fragment="1">NO RETURNS.</b></p>', 'Chêne Gear', 'Accessories', '{"activity:lifestyle","sub:book"}', 'active', NULL, 4.8, 12, 100, 1253),
  ('richardson-5-panel-chene-leather-patch-hat', '5-Panel Leather Patch Cap', '<p>Chêne Gear''s structured mesh-back caps feature a front panel that holds its shape season after season, paired with breathable, mesh back panels that keep you cool from the pre-dawn boat ride to the last retrieve of the day. A snapback closure allows for a dialed-in fit.</p>', 'Chêne Gear', 'Headwear', '{"activity:lifestyle"}', 'active', NULL, 4.8, 12, 35, 1154),
  ('chene-gear-gift-card', 'Chêne Gear Gift Card', '<p>The Chêne Gift Card is the easy call when you want them to choose for themselves. Delivered by email with instructions to redeem online.</p>', 'Chêne Gear', 'Gift Card', '{"channel:retail-only","hide-from-all-products","merch:no-upsell"}', 'active', NULL, 4.8, 12, 10, 9955),
  ('copy-of-chene-logo-rope-hat', 'Performance Waterproof PVC Patch Cap', '<p>When the temperature climbs and shows no sign of slowing down, the last thing you need is your hat working against you. Chêne Gear''s performance caps are built from lightweight, moisture-wicking fabric with a low-profile construction that stays out of your way. The adjustable closure provides a secure fit.</p>', 'Chêne Gear', 'Headwear', '{"activity:lifestyle"}', 'active', NULL, 4.8, 12, 35, 1156),
  ('chene-die-cut-sticker-pack', 'Sticker Pack', '<p>A good deep freezer, laptop or Yeti cooler should be free of blank space, the Sticker Pack aims to make that happen. Six die-cut stickers, perfect for repping Chene wherever you see fit.</p>', 'Chêne Gear', 'Accessories', '{"activity:lifestyle","sub:stickers"}', 'active', NULL, 4.8, 12, 15, 1257),
  ('2s-wader-mossy-oak-bottomland', 'Mossy Oak Bottomland 2S Wader', '<p>Busted seams retire more waders than anything else. The 2S Wader limits that possibility by only having two seams, a body-length seam down the side and another that runs from below the zipper and up your back. We furthered that "less is more" approach by removing excess fabric that''s prone to catching on the edges of boats and pit blinds. The 4-layer laminate blocks out all forms of moisture, but lets water vapor escape so things don''t get swampy when temperature or output increases. The boot construction and face fabric are more than tough enough for run-ins with sunken trees and busting sheets of ice. Years of testing were aimed at delivering the one thing we all want, waders that last -- the 2S Wader.</p>', 'Chêne Gear', 'Waders', '{"activity:waterfowl","audience:mens","boldmetrics:mens_2s_wader_alpha","feature:breathable","feature:waterproof","feature:windproof","merch:bestseller","merch:no-upsell","series:2s","YGroup_2S_Wader"}', 'active', 'Best Seller', 5, 198, 1150, 158),
  ('2s-wader-brown', 'Brown 2S Wader', '<p>Busted seams retire more waders than anything else. The 2S Wader limits that possibility by only having two seams, a body-length seam down the side and another that runs from below the zipper and up your back. We furthered that "less is more" approach by removing excess fabric that''s prone to catching on the edges of boats and pit blinds. The 4-layer laminate blocks out all forms of moisture, but lets water vapor escape so things don''t get swampy when temperature or output increases. The boot construction and face fabric are more than tough enough for run-ins with sunken trees and busting sheets of ice. Years of testing were aimed at delivering the one thing we all want, waders that last -- the 2S Wader.</p>', 'Chêne Gear', 'Waders', '{"activity:waterfowl","audience:mens","boldmetrics:mens_2s_wader_alpha","feature:breathable","feature:waterproof","feature:windproof","merch:bestseller","merch:no-upsell","series:2s","YGroup_2S_Wader"}', 'active', 'Best Seller', 5, 229, 1150, 159),
  ('2s-wader-mossy-oak-original-bottomland', 'Mossy Oak Original Bottomland 2S Wader', '<p>Busted seams retire more waders than anything else. The 2S Wader limits that possibility by only having two seams, a body-length seam down the side and another that runs from below the zipper and up your back. We furthered that "less is more" approach by removing excess fabric that''s prone to catching on the edges of boats and pit blinds. The 4-layer laminate blocks out all forms of moisture, but lets water vapor escape so things don''t get swampy when temperature or output increases. The boot construction and face fabric are more than tough enough for run-ins with sunken trees and busting sheets of ice. Years of testing were aimed at delivering the one thing we all want, waders that last -- the 2S Wader.</p>', 'Chêne Gear', 'Waders', '{"activity:waterfowl","audience:mens","boldmetrics:mens_2s_wader_alpha","feature:breathable","feature:waterproof","feature:windproof","merch:bestseller","merch:no-upsell","series:2s","YGroup_2S_Wader"}', 'active', NULL, 4.8, 12, 1150, 160),
  ('2s-wader-mossy-oak-original-treestand', 'Mossy Oak Original Treestand 2S Wader', '<p>Busted seams retire more waders than anything else. The 2S Wader limits that possibility by only having two seams, a body-length seam down the side and another that runs from below the zipper and up your back. We furthered that "less is more" approach by removing excess fabric that''s prone to catching on the edges of boats and pit blinds. The 4-layer laminate blocks out all forms of moisture, but lets water vapor escape so things don''t get swampy when temperature or output increases. The boot construction and face fabric are more than tough enough for run-ins with sunken trees and busting sheets of ice. Years of testing were aimed at delivering the one thing we all want, waders that last -- the 2S Wader.</p>', 'Chêne Gear', 'Waders', '{"activity:waterfowl","audience:mens","boldmetrics:mens_2s_wader_alpha","feature:breathable","feature:waterproof","feature:windproof","merch:bestseller","merch:no-upsell","series:2s","YGroup_2S_Wader"}', 'active', NULL, 4.8, 12, 1150, 161),
  ('2s-wader-mossy-oak-original-shadow-grass', 'Mossy Oak Original Shadow Grass 2S Wader', '<p>Busted seams retire more waders than anything else. The 2S Wader limits that possibility by only having two seams, a body-length seam down the side and another that runs from below the zipper and up your back. We furthered that "less is more" approach by removing excess fabric that''s prone to catching on the edges of boats and pit blinds. The 4-layer laminate blocks out all forms of moisture, but lets water vapor escape so things don''t get swampy when temperature or output increases. The boot construction and face fabric are more than tough enough for run-ins with sunken trees and busting sheets of ice. Years of testing were aimed at delivering the one thing we all want, waders that last -- the 2S Wader.</p>', 'Chêne Gear', 'Waders', '{"activity:waterfowl","audience:mens","boldmetrics:mens_2s_wader_alpha","feature:breathable","feature:waterproof","feature:windproof","merch:bestseller","merch:no-upsell","series:2s","YGroup_2S_Wader"}', 'active', NULL, 4.8, 12, 1150, 162),
  ('floodline-velo-lightweight-boot', 'Floodline Velo Lightweight Boot', '<p>When the waterline and mercury are high, grab the Floodline Velo Boot. Lightweight and built around an air mesh lining for top-tier breathability, the Velo variant of our Floodline Boot is the solution to standing water and stifling temps. The EVA midsole provides total comfort for full days on foot, even when the pace picks up. The 100% waterproof construction is paired with our purpose-built tread system for total traction, rain or shine.</p>', 'Chêne Gear', 'Footwear', '{"activity:turkey","activity:waterfowl","audience:mens","feature:waterproof","material:rubber","series:floodline"}', 'active', NULL, 4.8, 12, 180, 763),
  ('custom-yeti-rambler-14-oz-stackable-mug', 'Custom YETI Rambler 14 oz. Stackable Mug', '<span data-mce-fragment="1">Unlike traditional camp mugs, this double-wall, vacuum-insulated body protects hands from hot or cold contents while keeping coffee, chili, or oatmeal nice and hot. And now, it stacks up and stores out of sight. Like all Rambler® Drinkware, the mug and lid are dishwasher safe. Please note: the mug''s wide opening means content may cool quicker. That''s why the mug comes with the MagSlider™ Lid.</span>', 'Chêne Gear', 'Drinkware', '{"activity:lifestyle"}', 'active', NULL, 4.8, 12, 40, 9964),
  ('sixty-series-check-fleece-half-zip-with-hood', 'Sixty Series Check Fleece Half Zip with Hood', '<p>Our Sixty Series gear is built for all-season versatility. Wear it solo on opening day or layer on top of it during the final stretch. Grid fleece delivers reliable warmth without sacrificing breathability and the streamlined fit layers easily without bunching.</p>', 'Chêne Gear', 'Base Layers', '{"activity:turkey","activity:waterfowl","audience:mens","boldmetrics:mens_60_series_alpha","feature:quick-dry","material:fleece","series:sixty","sub:base-layer-top","sub:mid-layer"}', 'active', NULL, 4.8, 12, 160, 465),
  ('wader-care-kit', 'Wader Care Kit', '<p>Keep your waders in optimal condition with the Wader Care Kit. The suite of trusted products from GEAR AID maintain the water-repellancy, boot condition and zipper function of your waders. Each kit includes a unique, upcycled bag crafted from repurposed wader material.</p>', 'Chêne Gear', 'Accessories', '{"activity:waterfowl"}', 'active', NULL, 4.8, 12, 50, 1266),
  ('waxed-canvas-sweater', 'Waxed Canvas Sweater', '<p>We paired the weather resistance of waxed canvas with the natural warmth of wool to build a foul-weather workhorse, the Waxed Canvas Sweater. The top half sheds water and the wool naturally insulates throughout the garment, even when wet. An interior sleeve lining makes it easier to layer when the forecast calls for colder temps.</p>', 'Chêne Gear', 'Sweaters', '{"activity:lifestyle","audience:mens","boldmetrics:mens_wax_wool_sweater","material:wax-canvas","material:wool","series:wax-canvas","sub:mid-layer"}', 'active', NULL, 4.8, 12, 275, 1067),
  ('camp-jacket', 'Camp Jacket', '<p>A good puffer jacket goes a long way. A great puffer jacket goes even further. With a top-tier insulation package that outperforms down when wet or compressed, and a fit that can easily be layered on top of, the Camp Jacket does just that. A fleece-lined collar and elastic cuffs also help retain much needed warmth while sealing out the wind. Top-to-bottom, the Camp Jacket sets the standard for puffer-jacket versatility.</p>', 'Chêne Gear', 'Jackets', '{"activity:lifestyle","activity:waterfowl","boldmetrics:mens_camp_alpha","feature:insulated","merch:corporate","sub:insulated"}', 'active', NULL, 4.8, 12, 240, 268),
  ('waxed-canvas-goose-down-vest', 'Waxed Canvas Goose Down Vest', '<p>Waxed canvas has been a long-standing staple in the duck woods. With solid durability, built-in weather protection and a worn-in feel to boot, it''s a no-brainer. The Waxed Canvas Goose Down Vest takes that a step further with the unmatched warmth of down insulation.</p>', 'Chêne Gear', 'Vests', '{"activity:lifestyle","activity:waterfowl","audience:mens","boldmetrics:mens_wax_canvas_vest_alpha","feature:insulated","feature:water-resistant","feature:windproof","material:down","material:wax-canvas","series:wax-canvas","sub:insulated"}', 'active', NULL, 4.8, 12, 300, 369),
  ('merino-quarter-zip', 'Merino Quarter Zip', '<p>Wool has been a staple in timber holes and treestands for generations, and rightfully so. It naturally wicks away moisture, mitigates odor, and it''s exceptionally warm, even if it''s soaked. The Merino Quarter-Zip uses the highest-quality wool to make the most of these performance traits with an upgrade to softness.</p>', 'Chêne Gear', 'Base Layers', '{"activity:turkey","activity:waterfowl","boldmetrics:mens_merino_quarter_alpha","material:merino","sub:base-layer-top"}', 'active', NULL, 4.8, 12, 125, 470),
  ('wool-duck-bill-beanie', 'Wool Duck Bill Beanie', '<p>The Wool Duck Bill Beanie combines the natural warmth of wool with a structured duck bill brim that keeps rain and snow off your face. Wear it pulled down in the blind or pushed back at the fire. Built to do both.</p>', 'Chêne Gear', 'Headwear', '{"activity:waterfowl","sub:beanie"}', 'active', NULL, 4.8, 12, 50, 1171),
  ('hydro-lok-insulated-jacket', 'Hydro-Lok Insulated Jacket', '<p>Sometimes, waterproof and windproof just aren''t enough. So we paired the field-proven weather protection of Hydro-Lok and our most advanced insulation to create an all-weather powerhouse. An adjustable hood, hem, and cuffs keep water and wind from creeping in while the tough-as-nails face fabric handles brambles and rogue branches with ease. The Hydro-Lok Insulated Jacket is built for the forecasts that everyone else hits "snooze" for.</p>', 'Chêne Gear', 'Jackets', '{"activity:waterfowl","audience:mens","boldmetrics:mens_hydro_insulated_alpha","feature:insulated","feature:waterproof","series:hydro-lok","sub:insulated"}', 'active', NULL, 4.8, 12, 500, 272),
  ('waterfowler-moleskin-shirt', 'Waterfowler Moleskin Shirt', '<p>Sometimes, the old way of doing things is the right way to do things. The Waterfowler Moleskin Shirt uses tried-and-true materials, construction and style to deliver a modern classic. Bone buttons and a heavyweight chamois cloth have all the hallmarks of lasting quality and classic looks.</p>', 'Chêne Gear', 'Shirts', '{"activity:lifestyle","activity:waterfowl","audience:mens","boldmetrics:mens_waterfowler_alpha","material:chamois","merch:corporate"}', 'active', NULL, 4.8, 12, 140, 9973),
  ('old-school-mallard-cap', 'Old School Mallard Cap', '<p>A nod to the hunting camps, hand-me-down calls, and worn-in gear that made you a hunter in the first place. Chêne Gear''s vintage-inspired caps are built from corduroy and washed fabrics with a deliberately aged look. The graphics carry the same species and scenes that have always mattered most.</p>', 'Chêne Gear', 'Headwear', '{"activity:lifestyle"}', 'active', NULL, 4.8, 12, 35, 1174),
  ('built-better-rope-patch-cap', 'Built Better Rope Patch Cap', '<p>Chêne Gear''s rope caps deliver a curved brim, signature rope detail across the front, and a fit that feels broken in from day one. Built to wear hard and look good doing it. Snapback closure allows for an adjustable fit.</p>', 'Chêne Gear', 'Headwear', '{"activity:lifestyle"}', 'active', NULL, 4.8, 12, 35, 1175),
  ('delta-hoodie', 'Delta Hoodie', '<p>The hoodie you''ll turn to when comfort is the goal. The soft fleece interior and looser fit make for an easy-wearing staple suited for tackling the camp to-do list or some fireside cold ones.</p>', 'Chêne Gear', 'Hoodies', '{"activity:lifestyle","audience:mens","boldmetrics:mens_delta_hoodie_alpha"}', 'active', NULL, 4.8, 12, 80, 976),
  ('washed-out-camo-logo-tee-s-s', 'Washed Out Camo Logo Tee S/S', '<p>The tee you reach for, not the one you save. Built on heavyweight 6.1 oz garment-dyed ring-spun cotton, finished after it''s sewn so it shows up soft and already broken in. The color reads worn-in from the first wear, and the heavier weight holds its shape wash after wash. Relaxed through the body with a twill-taped neck. Runs slightly trim from the dye, so size up if you want more room.</p>', 'Chêne Gear', 'T-Shirts', '{"activity:lifestyle","audience:mens","lifecycle:new-arrival","material:cotton"}', 'active', NULL, 4.8, 12, 35, 877),
  ('duck-cowboy-tee-s-s', 'Duck Cowboy Tee S/S', '<p>The soft one. Built on a lightweight tri-blend of cotton, polyester, and rayon that trades weight for a broken-in drape and just enough give to move with you. Subtle heathered color, breathable on warm days, and soft from the first wear. The graphic is screen printed to hold up wash after wash. Fits slightly closer than our cotton tees.</p>', 'Chêne Gear', 'T-Shirts', '{"activity:lifestyle","audience:mens","material:cotton"}', 'active', NULL, 4.8, 12, 35, 878),
  ('coffee-table-book-volume-two', 'Coffee Table Book - Volume Two', '<p> </p> <p data-mce-fragment="1"><span data-mce-fragment="1">In this 208 page, hardcover coffee table book you will experience the Chêne Gear obsession of waterfowl hunting. Featuring stunning photography, full recipes, hunting stories, underground photos and much more. </span></p> <p data-mce-fragment="1"><b data-mce-fragment="1">Limited quantities available.</b></p> <p data-mce-fragment="1"><b data-mce-fragment="1">NO RETURNS.</b></p>', 'Chêne Gear', 'Accessories', '{"activity:lifestyle","sub:book"}', 'active', NULL, 4.8, 12, 100, 1279),
  ('vintage-mallard-tee-s-s', 'Vintage Mallard Tee S/S', '<p>The tee you reach for, not the one you save. Built on heavyweight 6.1 oz garment-dyed ring-spun cotton, finished after it''s sewn so it shows up soft and already broken in. The color reads worn-in from the first wear, and the heavier weight holds its shape wash after wash. Relaxed through the body with a twill-taped neck. Runs slightly trim from the dye, so size up if you want more room.</p>', 'Chêne Gear', 'T-Shirts', '{"activity:lifestyle","audience:mens","material:cotton"}', 'active', NULL, 4.8, 12, 35, 880),
  ('mallard-sunrise-tee-s-s', 'Mallard Sunrise Tee S/S', '<p>The tee you reach for, not the one you save. Built on heavyweight 6.1 oz garment-dyed ring-spun cotton, finished after it''s sewn so it shows up soft and already broken in. The color reads worn-in from the first wear, and the heavier weight holds its shape wash after wash. Relaxed through the body with a twill-taped neck. Runs slightly trim from the dye, so size up if you want more room.</p>', 'Chêne Gear', 'T-Shirts', '{"activity:lifestyle","audience:mens","material:cotton"}', 'active', NULL, 4.8, 12, 35, 881),
  ('waxed-canvas-gun-sleeve-with-strap', 'Waxed Canvas Gun Sleeve with Strap', '<p>A waxed canvas sleeve that keeps your gun protected in the truck, the boat, or on the walk in. The waxed shell sheds water and breaks in over time, and the included strap makes it easy to carry. Built to last and to age well. Carries the Chêne mark.</p>', 'Chêne Gear', 'Accessories', '{"activity:waterfowl","material:wax-canvas","series:wax-canvas"}', 'active', NULL, 4.8, 12, 175, 1282),
  ('waxed-canvas-padded-gun-sleeve', 'Waxed Canvas Padded Gun Sleeve', '<p>Waxed Canvas blocks out the elements and thick open-cell padding keeps your gun from getting banged up. The Waxed Canvas Padded Gun Sleeve is built to protect your gun from moisture, mud, and rough rides into the field. Crazy Horse leather accents further that protection and classic design for a piece built to last generations.</p>', 'Chêne Gear', 'Accessories', '{"activity:waterfowl","material:wax-canvas","series:wax-canvas"}', 'active', NULL, 4.8, 12, 325, 1283),
  ('waxed-canvas-backpack', 'Waxed Canvas Backpack', '<p>Withstand the elements and time. The Waxed Canvas Backpack delivers classic looks and functional form built to last generations. Waxed canvas is a perennial staple in the duck woods because of its reliable toughness and natural weather-resistance, so that''s where we started. It''s fully padded to protect your gear with enough room to store everything you''ll need for a morning spent in the timber.</p>', 'Chêne Gear', 'Accessories', '{"activity:lifestyle","activity:waterfowl","material:wax-canvas","merch:corporate","series:wax-canvas","sub:bag"}', 'active', NULL, 4.8, 12, 350, 1284),
  ('waxed-canvas-large-duffle-bag', 'Waxed Canvas Large Duffle Bag', '<p>Tough-as-nails with plenty of class, the Waxed Canvas Duffle Bag uses tried-and-true construction for heritage style that will last generations. Crazy Horse leather and waxed canvas are renowned for their durability and weather-resistance, so it just makes sense that we started there. Antique brass hardware rounds out this classic piece of gear.</p>', 'Chêne Gear', 'Accessories', '{"activity:lifestyle","material:wax-canvas","merch:corporate","series:wax-canvas","sub:bag"}', 'active', NULL, 4.8, 12, 550, 1285),
  ('waxed-canvas-medium-duffle-bag', 'Waxed Canvas Medium Duffle Bag', '<p>Tough-as-nails with plenty of class, the Waxed Canvas Duffle Bag uses tried-and-true construction for heritage style that will last generations. Crazy Horse leather and waxed canvas are renowned for their durability and weather-resistance, so it just makes sense that we started there. Antique brass hardware rounds out this classic piece of gear.</p>', 'Chêne Gear', 'Accessories', '{"activity:lifestyle","material:wax-canvas","merch:corporate","series:wax-canvas","sub:bag"}', 'active', NULL, 4.8, 12, 450, 1286),
  ('waxed-canvas-square-duffle-bag', 'Waxed Canvas Square Duffle Bag', '<p>Tough-as-nails with plenty of class, the Waxed Canvas Duffle Bag uses tried-and-true construction for heritage style that will last generations. Crazy Horse leather and waxed canvas are renowned for their durability and weather-resistance, so it just makes sense that we started there. Antique brass hardware rounds out this classic piece of gear.</p>', 'Chêne Gear', 'Accessories', '{"activity:lifestyle","material:wax-canvas","merch:corporate","series:wax-canvas","sub:bag"}', 'active', NULL, 4.8, 12, 350, 1287),
  ('built-better-tee-l-s', 'Built Better Tee L/S', '<p>The long sleeve you reach for, not the one you save. Built on heavyweight garment-dyed ring-spun cotton, finished after it''s sewn so it shows up soft and already broken in. The color reads worn-in from the first wear, and the heavier weight holds its shape wash after wash. Relaxed through the body with a twill-taped neck and long sleeves. Runs slightly trim from the dye, so size up if you want more room.</p>', 'Chêne Gear', 'T-Shirts', '{"activity:lifestyle","audience:mens","material:cotton"}', 'active', NULL, 4.8, 12, 40, 888),
  ('sherpa-fleece-scout-boot', 'Sherpa Fleece Scout Boot', '<p>If there''s moisture on the ground, work to be done, and frigid forecasts ahead, turn to the Sherpa Fleece Scout Boot. The sturdy rubber overlay makes standing water and muck a non-factor while the sherpa fleece lining keeps your feet warm in colder temps. Full days spent on your feet are made easier thanks to a neoprene lining and midsole construction that prioritize comfort.</p>', 'Chêne Gear', 'Footwear', '{"activity:lifestyle","activity:turkey","activity:waterfowl","audience:mens","feature:insulated","feature:waterproof","material:rubber","series:scout","sub:insulated"}', 'active', NULL, 4.8, 12, 150, 789),
  ('womens-logo-crop-hoodie', 'Women''s Logo Crop Hoodie', '<p>The hoodie you''ll turn to when comfort is the goal. The soft fleece interior and dropped shoulder make for an easy-wearing staple.</p>', 'Chêne Gear', 'Hoodies', '{"activity:lifestyle","audience:womens"}', 'active', NULL, 4.8, 12, 60, 990),
  ('waxed-canvas-wading-vest', 'Waxed Canvas Wading Vest', '<p>A tribute to the flooded timber duck hunter and an essential piece for the minimalist. Built with a heritage waxed canvas that stands up to the elements, this vest is designed for those who value both rugged durability and streamlined functionality. It''s a modern take on a classic, combining traditional materials with purposeful design, providing all the utility you need without excess.</p>', 'Chêne Gear', 'Vests', '{"activity:waterfowl","audience:mens","feature:water-resistant","material:wax-canvas","series:wax-canvas","sub:shell"}', 'active', NULL, 4.8, 12, 300, 391),
  ('vintage-corduroy-rope-patch-cap', 'Vintage Corduroy Rope Patch Cap', '<p>A nod to the hunting camps, hand-me-down calls, and worn-in gear that made you a hunter in the first place. Chêne Gear''s vintage-inspired caps are built from corduroy and washed fabrics with a deliberately aged look. The graphics carry the same species and scenes that have always mattered most.</p>', 'Chêne Gear', 'Headwear', '{"activity:lifestyle"}', 'active', NULL, 4.8, 12, 35, 1192),
  ('old-school-goose-cap', 'Old School Goose Cap', '<p>A nod to the hunting camps, hand-me-down calls, and worn-in gear that made you a hunter in the first place. Chêne Gear''s vintage-inspired caps are built from corduroy and washed fabrics with a deliberately aged look. The graphics carry the same species and scenes that have always mattered most.</p>', 'Chêne Gear', 'Headwear', '{"activity:lifestyle"}', 'active', NULL, 4.8, 12, 35, 1193),
  ('old-school-goose-rope-cap', 'Old School Goose Rope Cap', '<p>Chêne Gear''s rope caps deliver a curved brim, signature rope detail across the front, and a fit that feels broken in from day one. Built to wear hard and look good doing it. Snapback closure allows for an adjustable fit.</p>', 'Chêne Gear', 'Headwear', '{"activity:lifestyle"}', 'active', NULL, 4.8, 12, 35, 1194),
  ('old-school-mallard-rope-cap', 'Old School Mallard Rope Cap', '<p>Chêne Gear''s rope caps deliver a curved brim, signature rope detail across the front, and a fit that feels broken in from day one. Built to wear hard and look good doing it. Snapback closure allows for an adjustable fit.</p>', 'Chêne Gear', 'Headwear', '{"activity:lifestyle"}', 'active', NULL, 4.8, 12, 35, 1195),
  ('youth-hydro-lok-insulated-jacket', 'Youth Hydro-Lok Insulated Jacket', '<p>Sometimes, waterproof and windproof just aren''t enough. So we paired the field-proven weather protection of Hydro-Lok and our most advanced insulation to create an all-weather powerhouse. An adjustable hood, hem, and cuffs keep water and wind from creeping in while the tough-as-nails face fabric handles brambles and rogue branches with ease. The Hydro-Lok Insulated Jacket is built for the forecasts that everyone else hits "snooze" for.</p>  <p>Identical construction to the Adult Hydro-Lok Insulated Jacket.</p>', 'Chêne Gear', 'Jackets', '{"activity:waterfowl","audience:youth","feature:insulated","feature:waterproof","series:hydro-lok","sub:insulated"}', 'active', NULL, 4.8, 12, 400, 296),
  ('custom-yeti-rambler-20-oz-travel-mug', 'Custom YETI Rambler 20 oz. Travel Mug', '<p>The Rambler 20 oz Travel Mug is built for the drive. The twist-on Stronghold Lid is the most leak-resistant lid YETI makes, the handle fits your grip, and the base fits a cup holder. Double-wall vacuum insulation keeps coffee hot from the driveway to the blind. Carries the Chêne mark. The Stronghold Lid is leak resistant, not leakproof, so it isn''t made for packing.</p>', 'YETI', 'Drinkware', '{"activity:lifestyle"}', 'active', NULL, 4.8, 12, 48, 9997),
  ('custom-yeti-rambler-20-oz-tumbler-with-magslider-lid', 'Custom YETI Rambler 20 oz. Tumbler with MagSlider Lid', '<p>The Rambler 20 oz Tumbler is the daily driver: morning coffee, afternoon ice, and everything after. Kitchen-grade 18/8 stainless steel and double-wall vacuum insulation hold the temperature, DuraCoat color won''t crack or fade, and the base drops into a cup holder. Carries the Chêne mark. The MagSlider Lid is splash resistant, not leakproof.</p>', 'YETI', 'Drinkware', '{"activity:lifestyle"}', 'active', NULL, 4.8, 12, 45, 9998),
  ('custom-yeti-rambler-25-oz-straw-mug', 'Custom YETI Rambler 25 oz. Straw Mug', '<p>The Rambler 25 oz Straw Mug pairs a comfortable handle with a straw lid for easy, all-day sipping at the desk, in camp, or in the truck. Double-wall vacuum insulation keeps ice locked in and the stainless steel body takes the daily abuse. Carries the Chêne mark. The Straw Lid is not leakproof and is not for hot or carbonated drinks.</p>', 'YETI', 'Drinkware', '{"activity:lifestyle"}', 'active', NULL, 4.8, 12, 48, 9999),
  ('custom-yeti-rambler-30-oz-travel-mug', 'Custom YETI Rambler 30 oz. Travel Mug', '<p>The Rambler 30 oz Travel Mug holds more for longer mornings and longer drives. The twist-on Stronghold Lid is the most leak-resistant lid YETI makes, the handle fits your grip, and double-wall vacuum insulation keeps coffee hot for hours. Carries the Chêne mark. The Stronghold Lid is leak resistant, not leakproof, so it isn''t made for packing.</p>', 'YETI', 'Drinkware', '{"activity:lifestyle"}', 'active', NULL, 4.8, 12, 52, 10000),
  ('custom-yeti-rambler-30-oz-tumbler-with-magslider-lid', 'Custom YETI Rambler 30 oz. Tumbler with MagSlider Lid', '<p>The Rambler 30 oz Tumbler carries you from a hot morning brew to iced coffee that lasts the afternoon. Kitchen-grade 18/8 stainless steel and double-wall vacuum insulation hold the temperature, DuraCoat color won''t crack or fade, and the base still fits most cup holders. Carries the Chêne mark. The MagSlider Lid is splash resistant, not leakproof.</p>', 'YETI', 'Drinkware', '{"activity:lifestyle"}', 'active', NULL, 4.8, 12, 50, 10001),
  ('custom-yeti-rambler-35-oz-straw-mug', 'Custom YETI Rambler 35 oz. Straw Mug', '<p>The Rambler 35 oz Straw Mug gives you more water between refills with the same comfortable handle and easy straw lid. Double-wall vacuum insulation keeps ice locked in and the stainless steel body holds up to daily use. Carries the Chêne mark. The Straw Lid is not leakproof and is not for hot or carbonated drinks.</p>', 'YETI', 'Drinkware', '{"activity:lifestyle"}', 'active', NULL, 4.8, 12, 52, 10002),
  ('turkey-feather-tee-s-s', 'Turkey Feather Tee S/S', '<p>The tee you reach for, not the one you save. Built on heavyweight 6.1 oz garment-dyed ring-spun cotton, finished after it''s sewn so it shows up soft and already broken in. The color reads worn-in from the first wear, and the heavier weight holds its shape wash after wash. Relaxed through the body with a twill-taped neck. Runs slightly trim from the dye, so size up if you want more room.</p>', 'Chêne Gear', 'T-Shirts', '{"activity:lifestyle","audience:mens","lifecycle:new-arrival","material:cotton"}', 'active', NULL, 4.8, 12, 35, 903),
  ('old-school-turkey-cap', 'Old School Turkey Cap', '<p>A nod to the hunting camps, hand-me-down calls, and worn-in gear that made you a hunter in the first place. Chêne Gear''s vintage-inspired caps are built from corduroy and washed fabrics with a deliberately aged look. The graphics carry the same species and scenes that have always mattered most.</p>', 'Chêne Gear', 'Headwear', '{"activity:lifestyle"}', 'active', NULL, 4.8, 12, 35, 1204),
  ('old-school-turkey-rope-cap', 'Old School Turkey Rope Cap', '<p>Chêne Gear''s rope caps deliver a curved brim, signature rope detail across the front, and a fit that feels broken in from day one. Built to wear hard and look good doing it. Snapback closure allows for an adjustable fit.</p>', 'Chêne Gear', 'Headwear', '{"activity:lifestyle"}', 'active', NULL, 4.8, 12, 35, 1205),
  ('grove-boot', 'Grove Boot', '<p>A leather boot should handle years of wear and tear, even more miles, and look good doing it. The Grove Boot does just that. Starting with Crazy Horse leather, a staple in western saddle-making for decades, we prioritized ultra-wearable durability. The water-resistant toughness of the leather is paired with INSITE® insoles for superior underfoot comfort.</p>', 'Chêne Gear', 'Footwear', '{"activity:lifestyle","audience:mens","material:leather","merch:bestseller"}', 'active', NULL, 4.8, 12, 210, 806),
  ('cypress-2s-wader', 'Cypress 2S Wader', '<p>Busted seams retire more waders than anything else. The 2S Wader limits that possibility by only having two seams, a body-length seam down the side and another that runs from below the zipper and up your back. We furthered that "less is more" approach by removing excess fabric that''s prone to catching on the edges of boats and pit blinds. The 4-layer laminate blocks out all forms of moisture, but lets water vapor escape so things don''t get swampy when temperature or output increases. The boot construction and face fabric are more than tough enough for run-ins with sunken trees and busting sheets of ice. Years of testing were aimed at delivering the one thing we all want, waders that last -- the 2S Wader.</p>', 'Chêne Gear', 'Waders', '{"activity:waterfowl","audience:mens","boldmetrics:mens_2s_wader_alpha","feature:breathable","feature:waterproof","feature:windproof","merch:bestseller","merch:no-upsell","series:2s","YGroup_2S_Wader"}', 'active', NULL, 4.8, 12, 1150, 207),
  ('youth-scout-boot', 'Youth Scout Deck Boot', '<p>If there''s moisture on the ground and work to be done, turn to the Scout Boot. The sturdy rubber overlay makes standing water and muck a non-factor. Full days spent on your feet are made easier thanks to a neoprene lining and midsole construction that prioritize comfort.</p>', 'Chêne Gear', 'Footwear', '{"activity:lifestyle","activity:turkey","activity:waterfowl","audience:youth","feature:waterproof","material:rubber","series:scout"}', 'active', NULL, 4.8, 12, 100, 808),
  ('womens-scout-boot', 'Women''s Scout Boot', '<p>If there''s moisture on the ground and work to be done, turn to the Scout Boot. The sturdy rubber overlay makes standing water and muck a non-factor. Full days spent on your feet are made easier thanks to a neoprene lining and midsole construction that prioritize comfort.</p>', 'Chêne Gear', 'Footwear', '{"activity:lifestyle","activity:turkey","activity:waterfowl","audience:womens","feature:waterproof","material:rubber","series:scout"}', 'active', NULL, 4.8, 12, 120, 809),
  ('floodline-utility-boot', 'Floodline Utility Boot', '<p>All the hallmarks of a traditional rubber boot in a functional slip-on design. The Floodline Utility Boot tackles the to-do list with versatility, and more importantly, breathability. An air mesh grid liner boosts circulation and the EVA midsole furthers that comfort underfoot. The 100% waterproof construction is paired with our purpose-built tread system for total traction, rain or shine.</p>', 'Chêne Gear', 'Footwear', '{"activity:lifestyle","activity:turkey","activity:waterfowl","audience:mens","feature:waterproof","material:rubber","series:floodline"}', 'active', NULL, 4.8, 12, 150, 810),
  ('flying-duck-rope-mesh-back-cap', 'Flying Duck Rope Mesh Back Cap', '<p>Chêne Gear''s structured mesh-back caps feature a front panel that holds its shape season after season, paired with breathable, mesh back panels that keep you cool from the pre-dawn boat ride to the last retrieve of the day. A snapback closure allows for a dialed-in fit.</p>', 'Chêne Gear', 'Headwear', '{"activity:lifestyle"}', 'active', NULL, 4.8, 12, 35, 1211),
  ('built-better-ranch-logo-cap', 'Built Better Ranch Logo Cap', '<p>A structured ranch-style cap carrying the Built Better mark. Sits comfortably, holds its shape, and finished with an adjustable back for the right fit. Built for daily wear on the truck seat, at the ramp, or in the field.</p>', 'Chêne Gear', 'Headwear', '{"activity:lifestyle"}', 'active', NULL, 4.8, 12, 35, 1212),
  ('5-panel-waxed-cotton-mesh-back-cap', '5-Panel Waxed Cotton Mesh Back Cap', '<p>The same heritage material as the Chêne Gear Wax Canvas line, now in a cap. Waxed cotton construction that develops character with every hunt, water-resistant, naturally stiff, and built to soften and shape to you over time. An adjustable strap closure and clean profile make it versatile in and out of the field.</p>', 'Chêne Gear', 'Headwear', '{"activity:lifestyle"}', 'active', NULL, 4.8, 12, 35, 1213),
  ('2025-limited-edition-bandana', '2025 Limited Edition Bandana', '<p>A simple, useful piece for the field and everything around it. Wear it against sun and wind, wipe down a gun or a dog, or keep it in a pack for whatever comes up. The 2025 Limited Edition print won''t be run again once it is gone. Carries the Chêne mark.</p>', 'Chêne Gear', 'Accessories', '{"activity:lifestyle"}', 'active', NULL, 4.8, 12, 15, 1314),
  ('kettys-wader-tote-bag', 'Ketty''s Wader Tote Bag', NULL, 'Chêne Gear', 'Restored', '{"hide-from-all-products","series:kettys-shop"}', 'active', NULL, 4.8, 12, 80, 10015),
  ('take-to-the-timber-tee-s-s', 'Take to the Timber Tee S/S', '<p>The tee you reach for, not the one you save. Built on heavyweight 6.1 oz garment-dyed ring-spun cotton, finished after it''s sewn so it shows up soft and already broken in. The color reads worn-in from the first wear, and the heavier weight holds its shape wash after wash. Relaxed through the body with a twill-taped neck. Runs slightly trim from the dye, so size up if you want more room.</p>', 'Chêne Gear', 'T-Shirts', '{"activity:lifestyle","audience:mens","material:cotton"}', 'active', NULL, 4.8, 12, 35, 916),
  ('waterfowl-co-tee-s-s', 'Waterfowl Co. Tee S/S', '<p>The tee you reach for, not the one you save. Built on heavyweight 6.1 oz garment-dyed ring-spun cotton, finished after it''s sewn so it shows up soft and already broken in. The color reads worn-in from the first wear, and the heavier weight holds its shape wash after wash. Relaxed through the body with a twill-taped neck. Runs slightly trim from the dye, so size up if you want more room.</p>', 'Chêne Gear', 'T-Shirts', '{"activity:lifestyle","audience:mens","material:cotton"}', 'active', NULL, 4.8, 12, 35, 917),
  ('custom-yeti-flask', 'Custom YETI Flask', '<p>The YETI Flask is built for the pocket. A 7 oz single-wall stainless steel flask with an included funnel for clean fills, sized to ride along without getting in the way. Leakproof when closed, dishwasher safe, and finished in DuraCoat color that won''t peel or crack. Carries the Chêne mark on one side. Built for cold drinks only, not for hot, carbonated, or perishable beverages.</p>', 'Chêne Gear', 'Drinkware', '{"activity:lifestyle"}', 'active', NULL, 4.8, 12, 60, 10018),
  ('custom-yeti-yonder-600-ml-20-oz-water-bottle-with-yonder-tether-cap', 'Custom YETI Yonder 600 ml / 20 oz. Water Bottle with Yonder Tether Cap', '<p>The Yonder 20 oz Bottle trades insulation for weight. It is made from lightweight, shatter-resistant, BPA-free plastic for long miles where every ounce counts. The Yonder Tether Cap seals 100% leakproof and stays attached so you won''t lose it. Carries the Chêne mark. This bottle is not insulated and is not for hot or carbonated drinks.</p>', 'Chêne Gear', 'Drinkware', '{"activity:lifestyle"}', 'active', NULL, 4.8, 12, 32, 10019),
  ('custom-yeti-rambler-26-oz-water-bottle-with-chug-cap', 'Custom YETI Rambler 26 oz. Water Bottle with Chug Cap', '<p>The Rambler 26 oz Bottle hits the sweet spot: enough water for most of the day and still fits a pack. The Chug Cap opens with a quick twist of the TripleHaul handle for fast gulps, then seals 100% leakproof. Double-wall vacuum insulation keeps it cold and the stainless steel body handles the miles. Carries the Chêne mark. Not for use with carbonated drinks.</p>', 'Chêne Gear', 'Drinkware', '{"activity:lifestyle"}', 'active', NULL, 4.8, 12, 50, 10020),
  ('5-panel-logo-patch-cap', '5-Panel Logo Patch Cap', '<p>A clean 5-panel cap with a woven logo patch on the front. Low profile, structured enough to hold its shape, and finished with an adjustable closure for a dialed fit. The kind of cap you reach for without thinking about it.</p>', 'Chêne Gear', 'Headwear', '{"activity:lifestyle"}', 'active', NULL, 4.8, 12, 35, 1221),
  ('the-old-ways-tee-s-s', 'The Old Ways Tee S/S', '<p>The tee you reach for, not the one you save. Built on heavyweight 6.1 oz garment-dyed ring-spun cotton, finished after it''s sewn so it shows up soft and already broken in. The color reads worn-in from the first wear, and the heavier weight holds its shape wash after wash. Relaxed through the body with a twill-taped neck. Runs slightly trim from the dye, so size up if you want more room.</p>', 'Chêne Gear', 'T-Shirts', '{"activity:lifestyle","audience:mens","material:cotton"}', 'active', NULL, 4.8, 12, 35, 922),
  ('old-school-mallard-tee-s-s', 'Old School Mallard Tee S/S', '<p>The tee you reach for, not the one you save. Built on heavyweight 6.1 oz garment-dyed ring-spun cotton, finished after it''s sewn so it shows up soft and already broken in. The color reads worn-in from the first wear, and the heavier weight holds its shape wash after wash. Relaxed through the body with a twill-taped neck. Runs slightly trim from the dye, so size up if you want more room.</p>', 'Chêne Gear', 'T-Shirts', '{"activity:lifestyle","audience:mens","material:cotton"}', 'active', NULL, 4.8, 12, 35, 923),
  ('old-school-goose-tee-s-s', 'Old School Goose Tee S/S', '<p>The tee you reach for, not the one you save. Built on heavyweight 6.1 oz garment-dyed ring-spun cotton, finished after it''s sewn so it shows up soft and already broken in. The color reads worn-in from the first wear, and the heavier weight holds its shape wash after wash. Relaxed through the body with a twill-taped neck. Runs slightly trim from the dye, so size up if you want more room.</p>', 'Chêne Gear', 'T-Shirts', '{"activity:lifestyle","audience:mens","material:cotton"}', 'active', NULL, 4.8, 12, 35, 924),
  ('old-school-turkey-tee-s-s', 'Old School Turkey Tee S/S', '<p>The tee you reach for, not the one you save. Built on heavyweight 6.1 oz garment-dyed ring-spun cotton, finished after it''s sewn so it shows up soft and already broken in. The color reads worn-in from the first wear, and the heavier weight holds its shape wash after wash. Relaxed through the body with a twill-taped neck. Runs slightly trim from the dye, so size up if you want more room.</p>', 'Chêne Gear', 'T-Shirts', '{"activity:lifestyle","audience:mens","material:cotton"}', 'active', NULL, 4.8, 12, 35, 925),
  ('vintage-stamp-tee-s-s', 'Vintage Stamp Tee S/S', '<p>The tee you reach for, not the one you save. Built on heavyweight 6.1 oz garment-dyed ring-spun cotton, finished after it''s sewn so it shows up soft and already broken in. The color reads worn-in from the first wear, and the heavier weight holds its shape wash after wash. Relaxed through the body with a twill-taped neck. Runs slightly trim from the dye, so size up if you want more room.</p>', 'Chêne Gear', 'T-Shirts', '{"activity:lifestyle","audience:mens","material:cotton"}', 'active', NULL, 4.8, 12, 35, 926),
  ('outboard-tee-s-s', 'Outboard Tee S/S', '<p>A clean everyday tee built on soft, combed ring-spun cotton and bio-washed for a broken-in feel that lasts. The combed yarn gives it a smooth hand and a sharp print surface, and the cotton is responsibly sourced and finished with low-impact dyes. The graphic is screen printed to resist cracking and fading. Midweight and made to be worn hard.</p>', 'Chêne Gear', 'T-Shirts', '{"activity:lifestyle","audience:mens","material:cotton"}', 'active', NULL, 4.8, 12, 35, 927),
  ('flight-tee-s-s', 'Flight Tee S/S', '<p>A clean everyday tee built on soft, combed ring-spun cotton and bio-washed for a broken-in feel that lasts. The combed yarn gives it a smooth hand and a sharp print surface, and the cotton is responsibly sourced and finished with low-impact dyes. The graphic is screen printed to resist cracking and fading. Midweight and made to be worn hard.</p>', 'Chêne Gear', 'T-Shirts', '{"activity:lifestyle","audience:mens","material:cotton"}', 'active', NULL, 4.8, 12, 35, 928),
  ('waxed-canvas-bevrage-sleeve', 'Waxed Canvas Beverage Sleeve', '<p>Keep it cold. Keep it classy. This beverage sleeve brings waxed canvas out of the hardwoods and onto the drink of your choice.</p>', 'Chêne Gear', 'Accessories', '{"activity:lifestyle","material:wax-canvas","series:wax-canvas"}', 'active', NULL, 4.8, 12, 15, 1329),
  ('emblem-tee-s-s', 'Emblem Tee S/S', '<p>The tee you reach for, not the one you save. Built on heavyweight 6.1 oz garment-dyed ring-spun cotton, finished after it''s sewn so it shows up soft and already broken in. The color reads worn-in from the first wear, and the heavier weight holds its shape wash after wash. Relaxed through the body with a twill-taped neck. Runs slightly trim from the dye, so size up if you want more room.</p>', 'Chêne Gear', 'T-Shirts', '{"activity:lifestyle","audience:mens","material:cotton"}', 'active', NULL, 4.8, 12, 35, 930),
  ('waxed-canvas-goose-down-jacket', 'Waxed Canvas Goose Down Jacket', '<p><meta charset="utf-8">The Waxed Canvas Goose Down Jacket builds on the proven combination of classic materials and modern performance, delivering the warmth and weather resistance you need from early season to late cold. A 10.10 oz waxed cotton canvas shell sheds wind and light moisture without sacrificing the rugged feel of traditional outerwear, while 100g of 600 fill-power natural goose down keeps you insulated through long sits and slow walks alike, reinforced throughout with antique brass YKK zippers and snap closures. A microfleece-lined collar and storm flap seal out drafts, lower hand warmer pockets with microfleece lining keep your hands ready when temperatures drop, and three chest pockets (snap-closure flap, hidden magnetic closure, and internal zippered) give you organized carry for calls, licenses, and essentials. Adjustable neoprene cuffs and a cinched bottom hem lock in heat when you need it most.</p>', 'Chêne Gear', 'Jackets', '{"activity:waterfowl","audience:mens","boldmetrics:mens_scout_jacket_alpha","feature:insulated","feature:waterproof","feature:windproof","material:down","material:wax-canvas","series:wax-canvas","sub:insulated"}', 'active', NULL, 4.8, 12, 400, 331),
  ('scout-jacket', 'Scout Windproof Jacket', '<p>Boat rides and ripping north winds, that''s what the Scout Jacket was built for. The 100% windproof construction is capped off with a DWR finish to repel moisture, while the fleece-lined interior makes no sacrifices in comfort. High and low handwarmer pockets compliment a streamlined fit that layers easily under waders.</p>', 'Chêne Gear', 'Jackets', '{"activity:lifestyle","activity:waterfowl","audience:mens","boldmetrics:mens_scout_jacket_alpha","feature:breathable","feature:windproof","material:fleece","merch:corporate","series:scout","sub:shell"}', 'active', NULL, 4.8, 12, 325, 332),
  ('camo-logo-tee-s-s', 'Camo Logo Tee S/S', '<p>A clean everyday tee built on soft, combed ring-spun cotton and bio-washed for a broken-in feel that lasts. The combed yarn gives it a smooth hand and a sharp print surface, and the cotton is responsibly sourced and finished with low-impact dyes. The graphic is screen printed to resist cracking and fading. Midweight and made to be worn hard.</p>', 'Chêne Gear', 'T-Shirts', '{"activity:lifestyle","audience:mens","material:cotton"}', 'active', NULL, 4.8, 12, 35, 933),
  ('flyweigh-jac-shirt', 'Flyweigh Jac-Shirt', '<p>The Flyweigh Jac-Shirt is designed with enough warmth, breathability, and stretch to be comfortable from pre-dawn boat rides to post-hunt breakfast. Top-tier insulation handles a wide range of temperatures with ease and a face fabric that prioritizes mobility ensures your range of motion isn''t a limiting factor. The tried-and-true construction delivers the field-ready toughness you''ve come to expect from Chene and classic styling fits right in at Sunday supper.</p>', 'Chêne Gear', 'Shirts', '{"activity:lifestyle","activity:waterfowl","audience:mens","boldmetrics:mens_waterfowler_alpha","feature:insulated","material:polyester","merch:corporate","series:flyweigh","sub:insulated"}', 'active', NULL, 4.8, 12, 220, 10034),
  ('fieldstone-boot', 'Fieldstone Boot', '<p>A leather boot should handle years of wear and tear, even more miles, and look good doing it. The Fieldstone Boot does just that. Starting with Crazy Horse leather, a staple in western saddle-making for decades, we prioritized ultra-wearable durability. The water-resistant toughness of the leather is paired with INSITE® insoles for superior underfoot comfort.</p>', 'Chêne Gear', 'Footwear', '{"activity:lifestyle","audience:mens","material:leather"}', 'active', NULL, 4.8, 12, 230, 835),
  ('custom-yeti-rambler-36-oz-water-bottle-with-chug-cap', 'Custom YETI Rambler 36 oz. Water Bottle with Chug Cap', '<p>The Rambler 36 oz Bottle is for days when stops are scarce. The Chug Cap opens with a twist of the TripleHaul handle for fast gulps, then seals 100% leakproof. Double-wall vacuum insulation keeps it cold for hours and the kitchen-grade stainless steel takes the miles. Carries the Chêne mark. Not for use with carbonated drinks.</p>', 'Chêne Gear', 'Drinkware', '{"activity:lifestyle"}', 'active', NULL, 4.8, 12, 60, 10036),
  ('custom-yeti-rambler-18oz-water-bottle-with-chug-cap', 'Custom YETI Rambler 18 oz. Water Bottle with Chug Cap', NULL, 'Chêne Gear', 'Drinkware', '{"activity:lifestyle"}', 'active', NULL, 4.8, 12, 45, 10037),
  ('custom-yeti-rambler-10-oz-stackable-lowball', 'Custom YETI Rambler 10 oz. Stackable Lowball', '<span data-mce-fragment="1">Unlike traditional camp mugs, this double-wall, vacuum-insulated body protects hands from hot or cold contents while keeping coffee, chili, or oatmeal nice and hot. And now, it stacks up and stores out of sight. Like all Rambler® Drinkware, the mug and lid are dishwasher safe. Please note: the mug''s wide opening means content may cool quicker. That''s why the mug comes with the MagSlider™ Lid.</span>', 'Chêne Gear', 'Drinkware', '{"activity:lifestyle"}', 'active', NULL, 4.8, 12, 35, 10038),
  ('custom-yeti-rambler-1-g-jug', 'Custom YETI Rambler 1 G Jug', '<p>The Rambler One Gallon Jug hauls enough water or coffee for a full day and a full crew. Double-wall vacuum insulation holds the temperature, the 100% leakproof MagDock Cap keeps every drop where it belongs, and the Glugger-Not vent makes for smooth pours instead of splashes. The BearFoot base keeps it from sliding around the truck bed. Carries the Chêne mark.</p>', 'Chêne Gear', 'Drinkware', '{"activity:lifestyle"}', 'active', NULL, 4.8, 12, 135, 10039),
  ('custom-yeti-rambler-18oz-water-bottle-with-straw-cap', 'Custom YETI Rambler 18 oz. Water Bottle with Straw Cap', NULL, 'Chêne Gear', 'Drinkware', '{"activity:lifestyle"}', 'active', NULL, 4.8, 12, 40, 10040),
  ('custom-yeti-rambler-26-oz-water-bottle-with-straw-cap', 'Custom YETI Rambler 26 oz. Water Bottle with Straw Cap', '<p>The Rambler 26 oz Bottle with the Straw Cap keeps cold water within easy reach all day, no tilting required. Double-wall vacuum insulation holds the cold and the kitchen-grade stainless steel takes the beating. Carries the Chêne mark. The Straw Cap is not leakproof and is not for hot or carbonated drinks.</p>', 'Chêne Gear', 'Drinkware', '{"activity:lifestyle"}', 'active', NULL, 4.8, 12, 50, 10041),
  ('custom-yeti-rambler-64-oz-water-bottle-with-chug-cap', 'Custom YETI Rambler 64 oz. Water Bottle with Chug Cap', '<p>The Rambler 64 oz Bottle carries enough water to get you through a full day without a refill. The Chug Cap opens with a twist of the TripleHaul handle for fast gulps and seals 100% leakproof, while double-wall vacuum insulation holds the cold and the stainless steel body handles the abuse. Carries the Chêne mark. Not for use with carbonated drinks.</p>', 'Chêne Gear', 'Drinkware', '{"activity:lifestyle"}', 'active', NULL, 4.8, 12, 70, 10042),
  ('lightweight-wader-pant', 'Lightweight Wader Pant', '<p>The perfect compliment to 2S Waders, these pants aren''t short on purpose-built comfort. The fleece lining and built-in stretch make sure of that. The tapered fit and integrated stirrups keep everything in place and bunch-free.</p>', 'Chêne Gear', 'Pants', '{"activity:waterfowl","audience:mens","boldmetrics:mens_wader_pant_alpha","material:polyester","sub:bottom","sub:mid-layer"}', 'active', NULL, 4.8, 12, 200, 743),
  ('sherpa-fleece-neck-gaiter', 'Sherpa Fleece Neck Gaiter', '<p>When the morning starts with busting ice, the Sherpa Fleece Neck Gaiter is the piece you reach for. Sherpa-fleece construction delivers serious warmth in a compact form while being soft against your face. Pull it up, fold it down, or layer it under a hood, it''s built for the coldest stints of the year.</p>', 'Chêne Gear', 'Headwear', '{"activity:waterfowl","sub:neck-gaiter"}', 'active', NULL, 4.8, 12, 50, 1244),
  ('sixty-series-check-fleece-half-zip', 'Sixty Series Check Fleece Half Zip', '<p>Our Sixty Series gear is built for all-season versatility. Wear it solo on opening day or layer on top of it during the final stretch. Grid fleece delivers reliable warmth without sacrificing breathability and the streamlined fit layers easily without bunching.</p>', 'Chêne Gear', 'Base Layers', '{"activity:turkey","activity:waterfowl","audience:mens","boldmetrics:mens_60_series_alpha","feature:quick-dry","material:fleece","series:sixty","sub:base-layer-top","sub:mid-layer"}', 'active', NULL, 4.8, 12, 150, 545),
  ('womens-sherpa-fleece-scout-boot', 'Women''s Sherpa Fleece Scout Boot', '<p>If there''s moisture on the ground, work to be done, and frigid forecasts ahead, turn to the Sherpa Fleece Scout Boot. The sturdy rubber overlay makes standing water and muck a non-factor while the sherpa fleece lining keeps your feet warm in colder temps. Full days spent on your feet are made easier thanks to a neoprene lining and midsole construction that prioritize comfort.</p>', 'Chêne Gear', 'Footwear', '{"activity:lifestyle","activity:turkey","activity:waterfowl","audience:womens","feature:insulated","feature:waterproof","material:rubber","series:scout","sub:insulated"}', 'active', NULL, 4.8, 12, 150, 846),
  ('alpaca-heavyweight-crew-sock', 'Alpaca Heavyweight Crew Sock', '<p>Alpaca wool naturally holds pockets of air which provide top-end insulation and temperature regulation. Beyond keeping your feet comfortable in most forecasts, this wool provides natural durability, breathability and odor mitigation.</p>', 'Chêne Gear', 'Socks', '{"activity:lifestyle","activity:turkey","activity:waterfowl","audience:mens","audience:womens","material:alpaca"}', 'active', NULL, 4.8, 12, 40, 10047),
  ('alpaca-heavyweight-mid-calf-sock', 'Alpaca Heavyweight Mid-Calf Sock', '<p>Alpaca wool naturally holds pockets of air which provide top-end insulation and temperature regulation. Beyond keeping your feet comfortable in most forecasts, this wool provides natural durability, breathability and odor mitigation.</p>', 'Chêne Gear', 'Socks', '{"activity:lifestyle","activity:turkey","activity:waterfowl","audience:mens","audience:womens","material:alpaca"}', 'active', NULL, 4.8, 12, 45, 10048),
  ('woven-label-patch-vintage-cap', 'Woven Label Patch Vintage Cap', '<p>A nod to the hunting camps, hand-me-down calls, and worn-in gear that made you a hunter in the first place. Chêne Gear''s vintage-inspired caps are built from corduroy and washed fabrics with a deliberately aged look. The graphics carry the same species and scenes that have always mattered most.</p>', 'Chêne Gear', 'Headwear', '{"activity:lifestyle"}', 'active', NULL, 4.8, 12, 35, 1249),
  ('5-panel-waxed-cotton-patch-cap', '5-Panel Waxed Cotton Patch Cap', '<p>The same heritage material as the Chêne Gear Wax Canvas line, now in a cap. Waxed cotton construction that develops character with every hunt, water-resistant, naturally stiff, and built to soften and shape to you over time. An adjustable strap closure and clean profile make it versatile in and out of the field.</p>', 'Chêne Gear', 'Headwear', '{"activity:lifestyle"}', 'active', NULL, 4.8, 12, 35, 1250),
  ('redland-fitted-glove', 'Redland Fitted Glove', '<p>Built to be the best-fitting and longest-lasting glove you own, the Redland Fitted Glove delivers durability without bulk. The snug fit enhances control when working with tools, setting decoys, or handling gear. Premium goatskin leather provides soft comfort and dexterity, while the split cow leather palm adds extra toughness for seasons of work to come.</p>', 'Chêne Gear', 'Gloves', '{"activity:lifestyle","activity:waterfowl","audience:mens","material:leather","series:redland"}', 'active', NULL, 4.8, 12, 70, 10051),
  ('redland-sherpa-lined-glove', 'Redland Sherpa-Lined Glove', '<p>Built for hands that work through winter, the Redland Sherpa-Lined Glove packs durability and sherpa-fleece warmth into a streamlined package. Premium goatskin leather provides soft comfort and dexterity, while the split cow leather palm adds extra toughness for seasons of work to come.</p>', 'Chêne Gear', 'Gloves', '{"activity:lifestyle","activity:waterfowl","audience:mens","feature:insulated","material:fleece","material:leather","series:redland","sub:insulated"}', 'active', NULL, 4.8, 12, 90, 10052),
  ('izembek-liner-glove', 'Izembek Liner Glove', '<p>The Izembek Liner Glove offers the dexterity to wrangle Texas-rigs with ease, while Merino Wool keeps your hands warm, even when wet. Suede on the thumb and index finger work seamlessly with the touch screen on your phone. Fit to layer on top of, these gloves are built to be the cornerstone of warm hands.</p>', 'Chêne Gear', 'Gloves', '{"activity:waterfowl","audience:mens","material:merino","material:suede","series:izembek"}', 'active', NULL, 4.8, 12, 50, 10053),
  ('izembek-glove', 'Izembek Glove', '<p>Warm hands shouldn''t come at the cost of easily loading that third shell. The snug fit and strategically-placed suede on our Izembek Glove allow for complete dexterity, while Merino wool makes no sacrifices in warmth. AX Suede on the thumb and index finger work seamlessly with the touch screen on your phone.</p>', 'Chêne Gear', 'Gloves', '{"activity:waterfowl","audience:mens","material:merino","material:suede","series:izembek"}', 'active', NULL, 4.8, 12, 80, 10054),
  ('izembek-fingerless-glove', 'Izembek Fingerless Glove', '<p>Warm hands shouldn''t come at the cost of easily loading that third shell. The snug fit and strategically-placed suede on our Izembek Gloves allow for complete dexterity, while Merino wool makes no sacrifices in warmth.</p>', 'Chêne Gear', 'Gloves', '{"activity:waterfowl","audience:mens","material:merino","material:suede","series:izembek"}', 'active', NULL, 4.8, 12, 65, 10055),
  ('over-under-glove', 'Over/Under Glove', '<p>Conditions change, your gloves should too. The Over/Under Glove pulls double duty as a glove with exceptional dexterity and a 100% windproof mitt. The deployable mitt blocks heat-sapping winds and stows away when a more precise touch is needed.</p>', 'Chêne Gear', 'Gloves', '{"activity:waterfowl","audience:mens","feature:insulated","feature:windproof","material:fleece","series:over-under"}', 'active', NULL, 4.8, 12, 80, 10056),
  ('hydro-lok-wool-lined-glove', 'Hydro-Lok Wool-Lined Glove', '<p>The lowest-profile waterproof glove in our lineup, built for weatherproof warmth and workability. The Hydro-Lok shell and waterproof insert shrug off water and wind while the Merino wool interior adds low-bulk warmth. A short cuff design tucks cleanly under your jacket sleeve.</p>', 'Chêne Gear', 'Gloves', '{"activity:waterfowl","audience:mens","feature:insulated","feature:waterproof","feature:windproof","series:hydro-lok","sub:insulated"}', 'active', NULL, 4.8, 12, 110, 10057),
  ('hydro-lok-insulated-glove', 'Hydro-Lok Insulated Glove', '<p>Wind, water, and cold are forecast regulars come January. The Hydro-Lok Insulated Glove was designed to make quick work of all three. Extra insulation on the back of the glove prioritizes warmth, while a tactile panel on the palm provides a durable grip that works in all weather. The waterproof and windproof construction of the shell and insert guarantee warm and dry conditions for your digits. A long cuff design easily layers over your jacket sleeve.</p>', 'Chêne Gear', 'Gloves', '{"activity:waterfowl","audience:mens","feature:insulated","feature:waterproof","feature:windproof","series:hydro-lok","sub:insulated"}', 'active', NULL, 4.8, 12, 130, 10058),
  ('hydro-lok-insulated-lobster-mitt', 'Hydro-Lok Insulated Lobster Mitt', '<p>Wind, water, and cold are forecast regulars come January. The Hydro-Lok Insulated Lobster Mitt was designed to make quick work of all three. PrimaLoft™ insulation throughout the mitt prioritizes warmth, while a tactile panel on the palm provides a durable grip that works in all weather. The waterproof and windproof construction of the shell and insert guarantee warm and dry conditions for your digits. A long cuff design easily layers over your jacket sleeve.</p>', 'Chêne Gear', 'Gloves', '{"activity:waterfowl","audience:mens","feature:insulated","feature:waterproof","feature:windproof","series:hydro-lok","sub:insulated"}', 'active', NULL, 4.8, 12, 140, 10059),
  ('youth-hydro-lok-wool-lined-glove', 'Youth Hydro-Lok Wool-Lined Glove', '<p>The lowest-profile waterproof glove in our lineup, built for weatherproof warmth and workability. The Hydro-Lok shell and waterproof insert shrug off water and wind while the Merino wool interior adds low-bulk warmth. A short cuff design tucks cleanly under your jacket sleeve.</p>', 'Chêne Gear', 'Gloves', '{"activity:waterfowl","audience:youth","feature:insulated","feature:waterproof","feature:windproof","series:hydro-lok","sub:insulated"}', 'active', NULL, 4.8, 12, 80, 10060),
  ('floodline-fahrenheit-boot', 'Floodline Heavyweight Fahrenheit Boot', '<p>Hunt or work. Rain or snow. Cold or colder. The Floodline Fahrenheit Boot excels in every setting. PrimaLoft® insulation throughout the boot and Aerogel technology in the toe and footbed block out the cold from every angle. A three-part sole construction elevates comfort for full days in the field, even when carrying extra weight. Traction designed for every terrain and a full-length zipper round out the boot built for brutal conditions.</p>', 'Chêne Gear', 'Footwear', '{"activity:waterfowl","audience:mens","feature:insulated","feature:waterproof","material:rubber","series:floodline"}', 'active', NULL, 4.8, 12, 230, 861),
  ('washed-out-camo-logo-hoodie', 'Washed Out Camo Logo Hoodie', '<p>A well-worn feel from the jump, the Washed Out Camo Logo Hoodie has all the characteristics of a wardrobe staple, fresh off the rack. The loose fit, soft fleece interior, and faded classic patterns have all the hallmarks of your favorite hoodie.</p>', 'Chêne Gear', 'Hoodies', '{"activity:lifestyle","audience:mens","boldmetrics:mens_delta_hoodie_alpha"}', 'active', NULL, 4.8, 12, 80, 1062),
  ('izembek-beanie', 'Izembek Beanie', '<p>A simple knit beanie built for the cold end of the season. Warm, low-profile under a hood, and made to be worn hard. Named for Izembek, where the weather doesn''t give anything away.</p>', 'Chêne Gear', 'Headwear', '{"activity:waterfowl","audience:mens","material:merino","material:suede","series:izembek","sub:beanie"}', 'active', NULL, 4.8, 12, 50, 1263),
  ('performance-print-hat', 'Performance Print Cap', '<p>When the temperature climbs and shows no sign of slowing down, the last thing you need is your hat working against you. Chêne Gear''s performance caps are built from lightweight, moisture-wicking fabric with a low-profile construction that stays out of your way. The adjustable closure provides a secure fit.</p>', 'Chêne Gear', 'Headwear', '{"activity:lifestyle"}', 'active', NULL, 4.8, 12, 35, 1264),
  ('5-panel-built-better-mallard-cap', '5-Panel Built Better Mallard Cap', '<p>Chêne Gear''s structured mesh-back caps feature a front panel that holds its shape season after season, paired with breathable, mesh back panels that keep you cool from the pre-dawn boat ride to the last retrieve of the day. A snapback closure allows for a dialed-in fit.</p>', 'Chêne Gear', 'Headwear', '{"activity:lifestyle"}', 'active', NULL, 4.8, 12, 35, 1265),
  ('unstructured-woven-label-patch-cap', 'Unstructured Woven Label Patch Cap', '<p>Chêne Gear''s unstructured caps deliver a low-profile, relaxed fit and soft twill construction, the kind of hat that looks like it''s been with you a few seasons, right out of the box. Adjustable strap closure provides a dialed-in fit.</p>', 'Chêne Gear', 'Headwear', '{"activity:lifestyle"}', 'active', NULL, 4.8, 12, 35, 1266),
  ('5-panel-woven-label-patch-cap', '5-Panel Woven Label Patch Cap', '<p>Chêne Gear''s structured mesh-back caps feature a front panel that holds its shape season after season, paired with breathable, mesh back panels that keep you cool from the pre-dawn boat ride to the last retrieve of the day. A snapback closure allows for a dialed-in fit.</p>', 'Chêne Gear', 'Headwear', '{"activity:lifestyle"}', 'active', NULL, 4.8, 12, 35, 1267),
  ('merino-everyday-crew-sock', 'Merino Everyday Crew Sock', '<p>Wool socks just make sense. Natural warmth, moisture-wicking, and odor-mitigation properties make wool the ideal material for an everyday sock.</p>', 'Chêne Gear', 'Socks', '{"activity:lifestyle","activity:turkey","activity:waterfowl","audience:mens","audience:womens","material:merino"}', 'active', NULL, 4.8, 12, 30, 10068),
  ('merino-everyday-over-the-calf-sock', 'Merino Everyday Over-The-Calf Sock', '<p>Wool socks just make sense. Natural warmth, moisture-wicking, and odor-mitigation properties make wool the ideal material for an everyday sock.</p>', 'Chêne Gear', 'Socks', '{"activity:lifestyle","activity:turkey","activity:waterfowl","audience:mens","audience:womens","material:merino"}', 'active', NULL, 4.8, 12, 35, 10069),
  ('5-panel-vintage-mallard-patch-cap', '5-Panel Vintage Mallard Patch Cap', '<p>Chêne Gear''s structured mesh-back caps feature a front panel that holds its shape season after season, paired with breathable, mesh back panels that keep you cool from the pre-dawn boat ride to the last retrieve of the day. A snapback closure allows for a dialed-in fit.</p>', 'Chêne Gear', 'Headwear', '{"activity:lifestyle"}', 'active', NULL, 4.8, 12, 35, 1270),
  ('5-panel-est-2021-trucker-cap', '5-Panel EST 2021 Trucker Cap', '<p>Chêne Gear''s structured mesh-back caps feature a front panel that holds its shape season after season, paired with breathable, mesh back panels that keep you cool from the pre-dawn boat ride to the last retrieve of the day. A snapback closure allows for a dialed-in fit.</p>', 'Chêne Gear', 'Headwear', '{"activity:lifestyle"}', 'active', NULL, 4.8, 12, 35, 1271),
  ('5-panel-diamond-label-cap', '5-Panel Diamond Label Cap', '<p>Chêne Gear''s structured mesh-back caps feature a front panel that holds its shape season after season, paired with breathable, mesh back panels that keep you cool from the pre-dawn boat ride to the last retrieve of the day. A snapback closure allows for a dialed-in fit.</p>', 'Chêne Gear', 'Headwear', '{"activity:lifestyle"}', 'active', NULL, 4.8, 12, 35, 1272),
  ('5-panel-corner-patch-cap', '5-Panel Corner Patch Cap', '<p>Chêne Gear''s structured mesh-back caps feature a front panel that holds its shape season after season, paired with breathable, mesh back panels that keep you cool from the pre-dawn boat ride to the last retrieve of the day. A snapback closure allows for a dialed-in fit.</p>', 'Chêne Gear', 'Headwear', '{"activity:lifestyle"}', 'active', NULL, 4.8, 12, 35, 1273),
  ('washed-out-camo-logo-tee-l-s', 'Washed Out Camo Logo Tee L/S', '<p class="font-claude-response-body break-words whitespace-normal leading-[1.7]">Not every layer needs to work hard. Some just need to show up. The Washed Out Camo Logo Tee L/S is built for the time between seasons. Worn on the water, around camp, or out the door before first light. Classic Mossy Oak patterns run through a washed finish that breaks in the color and settles the look. Long sleeve because the season doesn''t always cooperate.</p>', 'Chêne Gear', 'Shirts', '{"activity:lifestyle","audience:mens"}', 'active', NULL, 4.8, 12, 40, 10074),
  ('coffee-table-book-volume-three', 'Coffee Table Book - Volume Three', '<p><meta charset="utf-8"><span data-teams="true">A celebration of stories and traditions from the field, this coffee table-worthy hardcover book is a visual journey that pays homage to the wonders of the outdoors and the moments we remember forever.</span></p>', 'Chêne Gear', 'Accessories', '{"activity:lifestyle","hide-from-all-products","sub:book"}', 'active', NULL, 4.8, 12, 100, 1375),
  ('youth-2s-wader', 'Youth 2S Wader', '<p>Busted seams retire more waders than anything else. The 2S Wader limits that possibility by only having two seams, a body-length seam down the side and another that runs from below the zipper and up your back. We furthered that "less is more" approach by removing excess fabric that''s prone to catching on the edges of boats and pit blinds. The 4-layer laminate blocks out all forms of moisture, but lets water vapor escape so things don''t get swampy when temperature or output increases. The boot construction and face fabric are more than tough enough for run-ins with sunken trees and busting sheets of ice. Years of testing were aimed at delivering the one thing we all want, waders that last -- the 2S Wader.</p>', 'Chêne Gear', 'Waders', '{"activity:waterfowl","audience:youth","feature:breathable","feature:waterproof","feature:windproof","merch:no-upsell","series:2s"}', 'active', NULL, 5, 44, 850, 276),
  ('2s-wading-pant', '2S Wading Pant', '<p>Busted seams retire more waders than anything else. The 2S Wading Pant limits that possibility by only having two seams, a body-length seam down the side and another that runs from below the zipper and up your back. We furthered that "less is more" approach by removing excess fabric that''s prone to catching on the edges of boats and pit blinds. The 4-layer laminate blocks out all forms of moisture, but lets water vapor escape so things don''t get swampy when temperature or output increases. The boot construction and face fabric are more than tough enough for run-ins with sunken trees and busting sheets of ice. Years of testing were aimed at delivering the one thing we all want, waders that last -- the 2S Wading Pant.</p>', 'Chêne Gear', 'Pants', '{"activity:waterfowl","audience:mens","boldmetrics:mens_2s_wader_pant_alpha","feature:waterproof","merch:bestseller","merch:no-upsell","series:2s","sub:bottom"}', 'active', NULL, 4.8, 12, 850, 777),
  ('call-wallet', 'Mouth Call Wallet', '<p dir="ltr"><span>Fighting with clunky gear doesn''t fly, especially when birds are in earshot. The Mouth Call Wallet was developed to give you quick and silent access to a slew of diaphragm calls. The magnetic closure and dedicated call slots keep a half-dozen reeds secure and easily accessible for close encounters.</span></p>', 'Chêne Gear', 'Accessories', '{"activity:turkey","lifecycle:new-arrival"}', 'active', NULL, 4.8, 12, 30, 1378),
  ('deception-glove', 'Deception Glove', '<p dir="ltr"><span>Anything that helps you stay hidden in the turkey woods is a winner, even more so if it handles the heat and doesn''t slow you down. We designed the Deception Gloves with that in mind. Combining breathable fabric, total dexterity and customizable coverage, these gloves check every box for warmer sits and stalks.</span></p>', 'Chêne Gear', 'Gloves', '{"activity:turkey","audience:mens","feature:breathable","lifecycle:new-arrival","material:synthetic","series:deception"}', 'active', NULL, 4.8, 12, 40, 10079),
  ('deception-pant', 'Deception Pant', '<p><meta charset="utf-8"><meta charset="utf-8">Pants that don''t pinch or bind, with the space to comfortably carry essential gear. That was the goal, and the Deception Pant delivers. Built with durable stretch woven fabric and articulated knee construction, it''s cut for total freedom of movement. Zippered cargo pockets anchor the pant''s storage, offering a secure place for the odds and ends needed for a rip through the woods. Moisture on the ground and light precipitation won''t compromise comfort thanks to the DWR treatment.</p>', 'Chêne Gear', 'Pants', '{"activity:turkey","audience:mens","boldmetrics:mens_field_pant_num","feature:breathable","feature:water-resistant","lifecycle:new-arrival","material:polyester","series:deception"}', 'active', NULL, 4.8, 12, 160, 780),
  ('deception-turkey-vest', 'Deception Turkey Vest', '<p><meta charset="utf-8"><meta charset="utf-8">Speed kills. The gear you leave in the truck doesn''t. The Deception Turkey Vest carries exactly what you need for a rip through the turkey woods without the bulk that slows you down. Purpose-built pockets let you run a full call lineup and essential gear with no compromises, while dedicated storage for a fly-down wing, decoy, and hydration keeps everything in its place. More gear helps, but hauling the kitchen sink isn''t worth losing comfort or mobility. Foam padding along the shoulders and back manages heavier loads comfortably, even when that load includes a long walk out with a bird. A quick-deploy seat stows cleanly into its own compartment, and every pocket stays streamlined so your movement remains fast, quiet, and unrestricted.<br></p>', 'Chêne Gear', 'Accessories', '{"activity:turkey","audience:mens","audience:womens","audience:youth","lifecycle:new-arrival","series:deception"}', 'active', NULL, 4.8, 12, 350, 1381),
  ('hydro-lok-velo-rain-jacket', 'Hydro-Lok Velo Rain Jacket', '<p><meta charset="utf-8"><meta charset="utf-8">Unpredictable forecasts are the only guarantee in spring. The Hydro-Lok Velo Jacket was built to be rain gear that''s considerably more reliable than the weatherman. At just 12 ounces, this waterproof workhorse packs tight to save space without compromising on durability. The hood and hem have draw-cord adjustments to seal out wind and rain while hook-and-loop cuffs keep moisture from climbing up your sleeve. A pair of water-resistant pockets provide secure, quick-access storage for a phone or essential gear that needs to stay dry.</p>', 'Chêne Gear', 'Jackets', '{"activity:turkey","audience:mens","boldmetrics:mens_hydro_shell_alpha","feature:breathable","feature:waterproof","series:hydro-lok","sub:shell"}', 'active', NULL, 4.8, 12, 300, 382),
  ('deception-leafy-jacket', 'Deception Leafy Jacket', '<p><meta charset="utf-8"><meta charset="utf-8"><meta charset="utf-8">More cover is always better. But natural cover can be hard to come by in spring, even more so when closing the distance on a gobbler requires you to do the moving. The Deception Leafy Jacket uses 3D camouflage elements to physically disrupt your outline, which is your best shot at going undetected in the woods. An adjustable hood, hem and elastic cuffs keep the jacket in place, ensuring your concealment is consistent when switching setup spots or going full-bore to cut down distance.<br></p>', 'Chêne Gear', 'Jackets', '{"activity:turkey","feature:breathable","lifecycle:new-arrival","material:mesh","merch:bestseller","series:deception","sub:shell"}', 'active', NULL, 4.8, 12, 140, 383),
  ('deception-face-mask', 'Deception Face Mask', '<p><meta charset="utf-8"><meta charset="utf-8">Getting busted by wary birds is a rite of passage, but it''s one we''d rather avoid. Concealment shouldn''t come at the cost of comfort, so the Deception Face Mask is built on a lightweight, breathable fabric that stays comfortable through long sits and quick moves. We also refused to sacrifice our field of view. An elastic drawcord and silicone nose strip keep the mask secure while calling or closing the distance.</p>', 'Chêne Gear', 'Accessories', '{"activity:turkey","audience:mens","audience:womens","audience:youth","feature:breathable","lifecycle:new-arrival","material:synthetic","series:deception","sub:neck-gaiter"}', 'active', NULL, 4.8, 12, 30, 1384),
  ('box-call-tee-ss', 'Box Call Tee S/S', '<p>The tee you reach for, not the one you save. Built on heavyweight 6.1 oz garment-dyed ring-spun cotton, finished after it''s sewn so it shows up soft and already broken in. The color reads worn-in from the first wear, and the heavier weight holds its shape wash after wash. Relaxed through the body with a twill-taped neck. Runs slightly trim from the dye, so size up if you want more room.</p>', 'Chêne Gear', 'T-Shirts', '{"activity:lifestyle","audience:mens","material:cotton"}', 'active', NULL, 4.8, 12, 35, 985),
  ('washed-out-camo-turkey-feather-tee-ss', 'Washed Out Camo Turkey Feather Tee S/S', '<p><meta charset="utf-8">Not every layer needs to work hard. Some just need to show up. The Washed Out Camo Logo Tee is built for the time between seasons. Worn on the water, around camp, or wherever the day takes you. Classic Mossy Oak patterns run through a washed finish that breaks in the color and settles the look.</p>', 'Chêne Gear', 'T-Shirts', '{"activity:lifestyle","audience:mens","material:cotton"}', 'active', NULL, 4.8, 12, 35, 986),
  ('turkey-patch-tee-ss', 'Turkey Patch Tee S/S', '<p>The tee you reach for, not the one you save. Built on heavyweight 6.1 oz garment-dyed ring-spun cotton, finished after it''s sewn so it shows up soft and already broken in. The color reads worn-in from the first wear, and the heavier weight holds its shape wash after wash. Relaxed through the body with a twill-taped neck. Runs slightly trim from the dye, so size up if you want more room.</p>', 'Chêne Gear', 'T-Shirts', '{"activity:lifestyle","audience:mens","lifecycle:new-arrival","material:cotton"}', 'active', NULL, 4.8, 12, 35, 987),
  ('vale-105-synthetic-hoodie', 'Vale 105 Synthetic Hoodie', '<p><meta charset="utf-8"><meta charset="utf-8">Spring turkey seasons can quickly skew hot and humid, especially when a hunt goes mobile and covering ground is on the docket. Enter the Vale 105 Hoodie. Breathable mesh fabric makes light work of warm-weather hunts while wicking away inevitable moisture. The fitted hood and built-in facemask provide concealment when things get up-close and personal. This hoodie is designed to beat the heat as a standalone staple and serve as the first layer of your system all year long.</p>', 'Chêne Gear', 'Base Layers', '{"activity:turkey","activity:waterfowl","audience:mens","boldmetrics:mens_60_series_alpha","feature:quick-dry","material:synthetic","merch:corporate","merch:new","series:vale"}', 'active', NULL, 4.8, 12, 120, 588),
  ('vale-105-synthetic-crew-l-s', 'Vale 105 Synthetic Crew L/S', '<p><meta charset="utf-8"><meta charset="utf-8">Spring turkey seasons can quickly skew hot and humid, especially when a hunt goes mobile and covering ground is on the docket. Enter the Vale 105 Crew. Breathable mesh fabric makes light work of warm-weather hunts while wicking away inevitable moisture. This crew is designed to beat the heat as a standalone staple and serve as the first layer of your system all year long.</p>', 'Chêne Gear', 'Base Layers', '{"activity:turkey","activity:waterfowl","audience:mens","boldmetrics:mens_60_series_alpha","feature:quick-dry","material:synthetic","merch:corporate","merch:new","series:vale"}', 'active', NULL, 4.8, 12, 100, 589),
  ('5-panel-waterfowl-co-trademark-cap', '5-Panel Waterfowl Co Trademark Cap', '<p>Chêne Gear''s structured mesh-back caps feature a front panel that holds its shape season after season, paired with breathable, mesh back panels that keep you cool from the pre-dawn boat ride to the last retrieve of the day. A snapback closure allows for a dialed-in fit.</p>', 'Chêne Gear', 'Headwear', '{"activity:lifestyle"}', 'active', NULL, 4.8, 12, 35, 1290),
  ('youth-americana-logo-tee-s-s', 'Youth Americana Logo Tee S/S', '<p>The tee they''ll actually want to wear. Built on soft, garment-dyed ring-spun cotton, finished after it''s sewn so it shows up broken in from the first wear. The color reads worn-in and the cotton holds its shape wash after wash. Cut for younger hunters.</p>', 'Chêne Gear', 'T-Shirts', '{"activity:lifestyle","audience:youth","material:cotton"}', 'active', NULL, 4.8, 12, 25, 991),
  ('americana-logo-tee-s-s', 'Americana Logo Tee S/S', '<p>The tee you reach for, not the one you save. Built on heavyweight 6.1 oz garment-dyed ring-spun cotton, finished after it''s sewn so it shows up soft and already broken in. The color reads worn-in from the first wear, and the heavier weight holds its shape wash after wash. Relaxed through the body with a twill-taped neck. Runs slightly trim from the dye, so size up if you want more room.</p>', 'Chêne Gear', 'T-Shirts', '{"activity:lifestyle","audience:mens","material:cotton"}', 'active', NULL, 4.8, 12, 35, 992),
  ('scout-pant', 'Scout Pant', '<p>When in doubt, the Scout Pant is the answer. Built-in stretch and the purpose-built fit prioritize comfort from long sits to high-output hunts. The lightweight nylon handles warmer temperatures with ease, and adding a layer underneath carries warmth later into the season. The lasting toughness of the woven fabric ensures all of this capability will stand-up to the wear-and-tear of harsh seasons and longer to-do lists.</p>', 'Chêne Gear', 'Pants', '{"activity:lifestyle","activity:turkey","activity:waterfowl","audience:mens","feature:breathable","feature:quick-dry","lifecycle:new-arrival","series:scout","sub:bottom"}', 'active', NULL, 4.8, 12, 160, 793),
  ('flux-jacket', 'Flux Jacket', '<p>One layer for every step of the hunt. The adaptive insulation breathes and moves more moisture when you''re dragging a sled or setting a big spread and retains more warmth when you''re stationary. The shell fabric has plenty of stretch and durability to accommodate high-output stints and rougher environments. It sounds too good to be true, but wear it all day without sweating or shivering and you''ll never leave home without it.</p>', 'Chêne Gear', 'Jackets', '{"activity:turkey","activity:waterfowl","audience:mens","feature:breathable","feature:insulated","feature:water-resistant","material:primaloft","merch:corporate","merch:new","sub:insulated","sub:mid-layer"}', 'active', NULL, 4.8, 12, 230, 394),
  ('forty-series-hooded-jacket', 'Forty Series Hooded Jacket', '<p>We built Forty Series to be a workhorse for the bulk of your waterfowl season. The soft shell fabric is wind-resistant and packs a good bit of warmth without being bulky. The tightly woven exterior handles run-ins with branches and brambles while a water repellent finish sheds moisture just as easily. This is the ideal outer layer right up until winter temperatures take hold.</p>', 'Chêne Gear', 'Jackets', '{"activity:waterfowl","audience:mens","feature:insulated","feature:water-resistant","lifecycle:new-arrival","merch:corporate","merch:new","sub:insulated","sub:shell"}', 'active', NULL, 4.8, 12, 200, 395),
  ('crossover-hoodie', 'Crossover Hoodie', '<p>The name says it all. The Crossover Hoodie excels in a timber hole, around town, or 20'' up in a tree. A wind-resistant, moisture-wicking exterior is paired with a brushed interior that has the comfort you''d expect from your favorite hoodie. Built-in stretch and scent mitigation make for an easy-wearing staple with added capability.</p>', 'Chêne Gear', 'Hoodies', '{"activity:lifestyle","activity:turkey","activity:waterfowl","audience:mens","lifecycle:new-arrival","material:fleece","merch:new","sub:insulated","sub:mid-layer"}', 'active', NULL, 4.8, 12, 120, 1096),
  ('flyweigh-hooded-vest', 'Flyweigh Hooded Vest', '<p>Designed to provide windproof warmth close to the body, the Flyweigh Hooded Vest is fit to be worn over baselayers or Sixty Series. Cut tighter to the body, this vest allows for an unrestricted range of motion even when layered on top of.</p>', 'Chêne Gear', 'Vests', '{"activity:lifestyle","activity:waterfowl","boldmetrics:mens_flyweigh_vest_alpha","feature:insulated","lifecycle:new-arrival","merch:corporate","merch:new","series:flyweigh","sub:insulated","sub:mid-layer"}', 'active', NULL, 4.8, 12, 240, 497),
  ('founders-reserve-waxed-jac-shirt', 'Founders'' Reserve Waxed Jac-Shirt', '<p>Part overshirt, part jacket, the Waxed Jac-Shirt is one of the most versatile pieces in the Founders'' Reserve collection. Built from premium British Millerain waxed cotton canvas, it offers dependable protection from changing weather while maintaining the timeless look of classic workwear. Whether layered over a hoodie in camp, worn through flooded timber, or thrown on around town, it''s designed to become one of those pieces you reach for without thinking.</p>', 'Chêne Gear', 'Jackets', '{"activity:waterfowl","audience:mens","material:cotton","material:wax-canvas","merch:corporate","merch:new","series:founders","series:wax-canvas","sub:insulated"}', 'active', 'New', 4.8, 12, 275, 398),
  ('founders-reserve-waxed-wading-jacket', 'Founders'' Reserve Waxed Wading Jacket', '<p>Inspired by generations of duck hunters who valued gear that earned its place over decades rather than seasons, the Waxed Wading Jacket brings timeless craftsmanship into the modern hunt. Built from premium British Millerain waxed cotton canvas, it delivers dependable protection from wind and wet conditions while developing the rich character that only waxed cotton canvas can achieve. Purpose-built with a wader-friendly fit, refined field storage, and weather-sealing details throughout, it''s equally at home in flooded timber before daylight as it is around camp after the hunt.</p>', 'Chêne Gear', 'Jackets', '{"activity:waterfowl","audience:mens","feature:insulated","material:cotton","material:wax-canvas","merch:new","series:founders","series:wax-canvas","sub:insulated","sub:shell"}', 'active', 'New', 4.8, 12, 380, 399),
