  ('trademark-tee-ss', 'Trademark Tee S/S', 'The tee you reach for, not the one you save. Built on heavyweight 6.1 oz garment-dyed ring-spun cotton, finished after it''s sewn so it shows up soft and already broken in. The color reads worn-in from the first wear, and the heavier weight holds its shape wash after wash. Relaxed through the body with a twill-taped neck. Runs slightly trim from the dye, so size up if you want more room.', 'Chêne Gear', 'T-Shirts', '{"activity:lifestyle","audience:mens","lifecycle:new-arrival","material:cotton","merch:new"}', 'active', 'New', 4.8, 12, 35, 1006),
  ('retrieve-tee-ss', 'Retrieve Tee S/S', 'The tee you reach for, not the one you save. Built on heavyweight 6.1 oz garment-dyed ring-spun cotton, finished after it''s sewn so it shows up soft and already broken in. The color reads worn-in from the first wear, and the heavier weight holds its shape wash after wash. Relaxed through the body with a twill-taped neck. Runs slightly trim from the dye, so size up if you want more room.', 'Chêne Gear', 'T-Shirts', '{"activity:lifestyle","audience:mens","lifecycle:new-arrival","material:cotton","merch:new"}', 'active', NULL, 4.8, 12, 35, 1007),
  ('kings-for-60-days-tee-ss', 'Kings For 60 Days Tee S/S', 'The tee you reach for, not the one you save. Built on heavyweight 6.1 oz garment-dyed ring-spun cotton, finished after it''s sewn so it shows up soft and already broken in. The color reads worn-in from the first wear, and the heavier weight holds its shape wash after wash. Relaxed through the body with a twill-taped neck. Runs slightly trim from the dye, so size up if you want more room.', 'Chêne Gear', 'T-Shirts', '{"activity:lifestyle","audience:mens","lifecycle:new-arrival","material:cotton","merch:new"}', 'active', NULL, 4.8, 12, 35, 1008),
  ('mallard-curl-tee-ss', 'Mallard Curl Tee S/S', 'The tee you reach for, not the one you save. Built on heavyweight 6.1 oz garment-dyed ring-spun cotton, finished after it''s sewn so it shows up soft and already broken in. The color reads worn-in from the first wear, and the heavier weight holds its shape wash after wash. Relaxed through the body with a twill-taped neck. Runs slightly trim from the dye, so size up if you want more room.', 'Chêne Gear', 'T-Shirts', '{"activity:lifestyle","audience:mens","lifecycle:new-arrival","material:cotton","merch:new"}', 'active', 'New', 4.8, 12, 35, 1009),
  ('duck-patch-tee-ss', 'Duck Patch Tee S/S', 'The tee you reach for, not the one you save. Built on heavyweight 6.1 oz garment-dyed ring-spun cotton, finished after it''s sewn so it shows up soft and already broken in. The color reads worn-in from the first wear, and the heavier weight holds its shape wash after wash. Relaxed through the body with a twill-taped neck. Runs slightly trim from the dye, so size up if you want more room.', 'Chêne Gear', 'T-Shirts', '{"activity:lifestyle","audience:mens","lifecycle:new-arrival","material:cotton","merch:new"}', 'active', NULL, 4.8, 12, 35, 1010),
  ('delta-pack', 'Delta Pack', '<p><meta charset="utf-8"><span data-contrast="none" lang="EN-US" class="TextRun SCXW16472626 BCX0"><span class="NormalTextRun SCXW16472626 BCX0">Built for waterfowl hunters who refuse to choose between protection from the elements and functional organization, the Delta Pack brings both together in one purpose-built pack. An RF-welded chassis, durable TPU-coated fabrics, and weather-resistant YKK zippers protect your gear in wet conditions, while eight zippered pockets inside and out keep shells, calls, and essentials organized and secure. From long walks into flooded timber to wet boat bottoms and mornings in the marsh, every detail is designed to keep your gear protected, accessible, and ready for the hunt.</span></span><span class="EOP Selected SCXW16472626 BCX0" data-ccp-props=''{"134233117":false,"134233118":false,"335559685":720,"335559738":240,"335559739":240}''> </span></p>', 'Chêne Gear', 'Accessories', '{"activity:waterfowl","audience:mens","feature:water-resistant","lifecycle:new-arrival","merch:new","sub:bag"}', 'active', 'New', 4.8, 12, 300, 1411);

